INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('1', 'hSD01-001', 'oshiCharacter', 'OSR', NULL, 'hSD01/hSD01-001_OSR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-001_OSR.png', NULL, 5, NULL, NULL, 'でいりー', 'ときのそら', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Tokino Sora","oshi_skill":{"effect":"[Once per turn] Move 1 Cheer on your Stage to one of your holomem.","name":"Replacement","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Switch your opponent''s Center holomem with 1 of their Back holomem. Then, during this turn, your white Center holomem gets Arts +50.","name":"Then you''re an enemy?","timing":"Once per game"}},"es":{"name":"Tokino Sora","oshi_skill":{"effect":"[Una vez por turno] Cambia 1 Cheer de tu escenario a uno de tus holomen.","name":"Reemplazo","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Haz que el Centro holomen de tu oponente y 1 Back holomen se intercambien. Después, durante este turno, las Arts de tu Centro holomen blanco +50.","name":"¿Then you''re an enemy?","timing":"Una vez por partida"}},"id":{"name":"Tokino Sora","oshi_skill":{"effect":"[Sekali per giliran] Pindahkan 1 Cheer di stage milikmu ke holomen milikmu.","name":"Penggantian","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per game] Tukarkan Center holomem lawan dengan 1 Back holomem lawan. Setelah itu, selama giliran ini, Arts dari Center holomem putih milikmu +50.","name":"Kalau begitu kamu musuh?","timing":"Sekali per permainan"}},"ja":{"name":"ときのそら","oshi_skill":{"effect":"[ターンに1回]自分のステージのエール1枚を、自分のホロメンに付け替える。","name":"リプレイスメント","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]相手のセンターホロメンとバックホロメン1人を交代させる。その後、このターンの間、自分の白センターホロメンのアーツ+50。","name":"じゃあ敵だね？","timing":"ゲームに1回"}},"ko":{"name":"토키노 소라","oshi_skill":{"effect":"[턴에 1번]자신의 스테이지의 에일 1장을 자신의 홀로멘에게 갈아붙인다.","name":"리플레이스먼트","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번] 상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다. 그 후, 이 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50.","name":"그럼 적이네?","timing":"게임에 1번"}},"tc":{"name":"時乃空","oshi_skill":{"effect":"[每回合1次]將自己舞台上的1張應援改附到自己的holomen。","name":"替換","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場遊戲1次]使對手的中心Holo成員與1位後台Holo成員交換。之後，在這個回合中，自己的白色中心Holo成員的藝術+50。","name":"那就是敵人囉？","timing":"每場對戰1次"}},"th":{"name":"โตกิโนะ โซระ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ย้ายเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนของคุณ","name":"Replacement","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] สลับเซ็นเตอร์โฮโลเมนของคู่ต่อสู้กับแบ็กโฮโลเมน 1 คนของคู่ต่อสู้ หลังจากนั้น ในระหว่างเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเมนสีขาวของคุณ +50","name":"งั้นเป็นศัตรูสิ?","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{"en":[{"answer":"Yes, it can be used.You will resolve only ''During this turn, your white center holomem gets Arts+50.'' without resolving ''Swap your opponent''s center holomem with 1 back holomem. ''.","question":"Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can it be used when opponent has no center holomem or back holomem?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q204（October 04, 2024）"},{"answer":"Yes, it is possible.","question":"Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can resting holomem be chosen when swapping opponent''s center holomem and back holomem?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q203（October 04, 2024）"},{"answer":"The player who used ''So, That Makes You My Enemy?'' will choose.","question":"When the turn player uses SP Oshi skill ''So, that Makes You My Enemy?'', who chooses the back holomem to swap?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q118（September 21, 2024）"},{"answer":"Yes, it can be used.","question":"Can hSD01-001〈Tokino Sora〉''s Oshi skill ''Replacement'' be used even if there is no cheer on the stage?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q1（September 21, 2024）"}],"es":[{"answer":"Sí, puedes usarla. Para resolver el efecto tanto como sea posible, la parte de “Intercambia el Holomen central y un Holomen de respaldo del oponente” no se resuelve, y solo se resuelve la parte “Luego, durante este turno, los Artes de tu Holomen central blanco obtienen +50.”","question":"Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, si el oponente no tiene un Holomen central o no tiene Holomen de respaldo, ¿puedo usar esta habilidad SP Oshi Skill?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"Sí, puedes hacerlo.","question":"Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, cuando intercambias el Holomen central y el Holomen de respaldo del oponente, ¿puedes elegir un Holomen que esté descansando?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"Lo elige el jugador del turno que usó “¿Entonces eres mi enemigo?”.","question":"Cuando el jugador del turno usa la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?”, ¿quién elige al Holomen de respaldo que se intercambiará?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"Sí, puedes usarla.","question":"¿Se puede usar la habilidad Oshi Skill “Reemplazo” de hSD01-001〈ときのそら〉 incluso si no hay cartas de Apoyo en el Escenario?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"id":[{"answer":"Ya, bisa digunakan. Untuk menyelesaikan efek sejauh mungkin, bagian \"Tukar Center Holomen lawan dengan satu Back Holomen lawan.\" tidak akan diselesaikan, dan hanya bagian \"Setelah itu, hingga akhir giliran ini, Arts Center Putih-mu +50.\" yang akan diselesaikan.","question":"Tentang SP Oshi Skill hSD01-001〈ときのそら〉 \"じゃあ敵だね？\": jika tidak ada Center Holomen atau tidak ada Back Holomen di panggung lawan, apakah SP Oshi Skill ini masih bisa digunakan?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"Ya, boleh.","question":"Tentang SP Oshi Skill hSD01-001〈ときのそら〉 \"じゃあ敵だね？\": saat menukar Center Holomen dan Back Holomen lawan, bolehkah memilih Holomen yang sedang istirahat?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"Pemain yang menggunakan \"じゃあ敵だね？\" pada giliran tersebut.","question":"Saat pemain giliran menggunakan SP Oshi Skill \"じゃあ敵だね？\", siapa yang memilih Back Holomen yang akan ditukar?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"Ya, bisa digunakan.","question":"Apakah Oshi Skill hSD01-001〈ときのそら〉 \"リプレイスメント\" bisa digunakan meskipun tidak ada Yell di panggung?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"ja":[{"answer":"はい、使用できます。可能な限り効果を解決するため「相手のセンターホロメンとバックホロメン１人を交代させる。」については解決せず、「その後、このターンの間、自分の白センターホロメンのアーツ+50。」の部分のみ解決します。","question":"hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のステージにセンターホロメンがいない場合や、バックホロメンがいない場合に、このSP推しスキルを使用することはできますか。","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"はい、できます。","question":"hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のセンターホロメンとバックホロメンを交代させる時、お休みしているホロメンを選ぶことはできますか？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"「じゃあ敵だね？」を使ったターンプレイヤーになります。","question":"ターンプレイヤーがSP推しスキル「じゃあ敵だね？」を使った時、交代させるバックホロメンを選ぶのはどちらのプレイヤーですか？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"はい、使用できます。","question":"hSD01-001〈ときのそら〉の推しスキル「リプレイスメント」はステージにエールが無くても使用できますか？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"ko":[{"answer":"네, 사용할 수 있습니다. 가능한 범위에서 효과를 해결하기 때문에 「상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다.」 부분은 해결하지 않고, 「그 후, 이번 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50.」 부분만 해결합니다.","question":"hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대 스테이지에 센터 홀로멘이 없거나 백 홀로멘이 없을 경우에도 이 SP 오시 스킬을 사용할 수 있나요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"네, 가능합니다.","question":"hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대의 센터 홀로멘과 백 홀로멘을 교대시킬 때 휴식 중인 홀로멘을 선택할 수 있나요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"「그럼 적이네?」를 사용한 턴 플레이어입니다.","question":"턴 플레이어가 SP 오시 스킬 「그럼 적이네?」를 사용했을 때, 교대시킬 백 홀로멘을 선택하는 것은 어느 플레이어인가요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"네, 사용할 수 있습니다.","question":"hSD01-001〈ときのそら〉의 오시 스킬 「리플레이스먼트」는 스테이지에 에일이 없어도 사용할 수 있나요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"tc":[{"answer":"可以使用。為了盡可能解決效果，「讓對手的中央Holomen與1位後排Holomen互換位置。」這部分將不會解決，只會解決「之後，直到回合結束為止，自己的白色中央Holomen的藝能+50。」這部分。","question":"關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」如果對手舞台上沒有中央Holomen，或是沒有後排Holomen，能使用這個SP推し技能嗎？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"可以。","question":"關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」在讓對手的中央Holomen與後排Holomen互換位置時，可以選擇休息中的Holomen嗎？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"是使用「那就是敵人了？」的回合玩家選擇。","question":"當回合玩家使用SP推し技能「那就是敵人了？」時，選擇要互換位置的後排Holomen的是哪一位玩家？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"可以使用。","question":"hSD01-001〈ときのそら〉的推し技能「替換」在舞台上沒有應援時也能使用嗎？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"th":[{"answer":"ได้ สามารถใช้ได้ ในส่วนของการพยายามแก้ผลให้มากที่สุด ถ้าส่วนที่ว่า “สลับ センターホロメン ของฝ่ายตรงข้าม กับ バックホロメン 1 คน” ไม่สามารถแก้ได้ จะข้ามส่วนนั้นไป และแก้เฉพาะส่วนที่ว่า “จากนั้น ในช่วงเทิร์นนี้ アーツ ของ 白センター ホロメン ของตัวเอง +50”","question":"เกี่ยวกับ SP 推しスキル 「งั้นเป็นศัตรูสิ?」 ของ hSD01-001〈ときのそら〉 ถ้าฝั่งตรงข้ามไม่มี センターホロメン บนสเตจ หรืไม่มี バックホロメン จะสามารถใช้สกิลนี้ได้ไหม","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"ได้ สามารถเลือกได้","question":"เกี่ยวกับ SP 推しスキル 「งั้นเป็นศัตรูสิ?」 ของ hSD01-001〈ときのそら〉 เมื่อต้องสลับ センターホロメン กับ バックホロメン ของฝ่ายตรงข้าม สามารถเลือก ホロメン ที่อยู่ในสถานะพัก (お休み) ได้หรือไม่","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"ผู้เล่นที่ใช้ 「งั้นเป็นศัตรูสิ?」 ในเทิร์นนั้น เป็นผู้เลือก","question":"เมื่อผู้เล่นที่กำลังเป็นเทิร์นใช้ SP 推しスキル 「งั้นเป็นศัตรูสิ?」 ผู้เล่นคนไหนเป็นคนเลือก バックホロメン ที่จะถูกสลับ","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"ได้ สามารถใช้ได้","question":"เกี่ยวกับ 推しスキル 「Replacement」 ของ hSD01-001〈ときのそら〉 ถ้าบนสเตจไม่มี エール จะยังใช้สกิลนี้ได้ไหม","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}]}', '6c048c53b76e6eb5b8a7c1b5a4072ee6fe480d933cd6d830cb971eff6c71409a', 'acd8165d02d7a1e9f0069a6cbe6d24f44d49b373902823e48fbfaef8ed8d4fd7', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white', '1');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '1');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (1, 'hSD01-001', 'hSD01-001 でいりー ときのそら リプレイスメント [ターンに1回]自分のステージのエール1枚を、自分のホロメンに付け替える。 じゃあ敵だね？ [ゲームに1回]相手のセンターホロメンとバックホロメン1人を交代させる。その後、このターンの間、自分の白センターホロメンのアーツ+50。 Tokino Sora Replacement [Once per turn] Move 1 Cheer on your Stage to one of your holomem. Then you''re an enemy? [Once per game] Switch your opponent''s Center holomem with 1 of their Back holomem. Then, during this turn, your white Center holomem gets Arts +50. 時乃空 替換 [每回合1次]將自己舞台上的1張應援改附到自己的holomen。 那就是敵人囉？ [每場遊戲1次]使對手的中心Holo成員與1位後台Holo成員交換。之後，在這個回合中，自己的白色中心Holo成員的藝術+50。 Tokino Sora Penggantian [Sekali per giliran] Pindahkan 1 Cheer di stage milikmu ke holomen milikmu. Kalau begitu kamu musuh? [Sekali per game] Tukarkan Center holomem lawan dengan 1 Back holomem lawan. Setelah itu, selama giliran ini, Arts dari Center holomem putih milikmu +50. 토키노 소라 리플레이스먼트 [턴에 1번]자신의 스테이지의 에일 1장을 자신의 홀로멘에게 갈아붙인다. 그럼 적이네? [게임에 1번] 상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다. 그 후, 이 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50. โตกิโนะ โซระ Replacement [ใช้ได้ 1 ครั้งต่อเทิร์น] ย้ายเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนของคุณ งั้นเป็นศัตรูสิ? [ใช้ได้ 1 ครั้งต่อเกม] สลับเซ็นเตอร์โฮโลเมนของคู่ต่อสู้กับแบ็กโฮโลเมน 1 คนของคู่ต่อสู้ หลังจากนั้น ในระหว่างเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเมนสีขาวของคุณ +50 Tokino Sora Reemplazo [Una vez por turno] Cambia 1 Cheer de tu escenario a uno de tus holomen. ¿Then you''re an enemy? [Una vez por partida] Haz que el Centro holomen de tu oponente y 1 Back holomen se intercambien. Después, durante este turno, las Arts de tu Centro holomen blanco +50.', 'Q204（2024.10.04） hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のステージにセンターホロメンがいない場合や、バックホロメンがいない場合に、このSP推しスキルを使用することはできますか。 はい、使用できます。可能な限り効果を解決するため「相手のセンターホロメンとバックホロメン１人を交代させる。」については解決せず、「その後、このターンの間、自分の白センターホロメンのアーツ+50。」の部分のみ解決します。 Q203（2024.10.04） hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のセンターホロメンとバックホロメンを交代させる時、お休みしているホロメンを選ぶことはできますか？ はい、できます。 Q118（2024.09.21） ターンプレイヤーがSP推しスキル「じゃあ敵だね？」を使った時、交代させるバックホロメンを選ぶのはどちらのプレイヤーですか？ 「じゃあ敵だね？」を使ったターンプレイヤーになります。 Q1（2024.09.21） hSD01-001〈ときのそら〉の推しスキル「リプレイスメント」はステージにエールが無くても使用できますか？ はい、使用できます。 Q204（October 04, 2024） Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can it be used when opponent has no center holomem or back holomem? Yes, it can be used.You will resolve only ''During this turn, your white center holomem gets Arts+50.'' without resolving ''Swap your opponent''s center holomem with 1 back holomem. ''. Q203（October 04, 2024） Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can resting holomem be chosen when swapping opponent''s center holomem and back holomem? Yes, it is possible. Q118（September 21, 2024） When the turn player uses SP Oshi skill ''So, that Makes You My Enemy?'', who chooses the back holomem to swap? The player who used ''So, That Makes You My Enemy?'' will choose. Q1（September 21, 2024） Can hSD01-001〈Tokino Sora〉''s Oshi skill ''Replacement'' be used even if there is no cheer on the stage? Yes, it can be used. Q204（2024.10.04） 關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」如果對手舞台上沒有中央Holomen，或是沒有後排Holomen，能使用這個SP推し技能嗎？ 可以使用。為了盡可能解決效果，「讓對手的中央Holomen與1位後排Holomen互換位置。」這部分將不會解決，只會解決「之後，直到回合結束為止，自己的白色中央Holomen的藝能+50。」這部分。 Q203（2024.10.04） 關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」在讓對手的中央Holomen與後排Holomen互換位置時，可以選擇休息中的Holomen嗎？ 可以。 Q118（2024.09.21） 當回合玩家使用SP推し技能「那就是敵人了？」時，選擇要互換位置的後排Holomen的是哪一位玩家？ 是使用「那就是敵人了？」的回合玩家選擇。 Q1（2024.09.21） hSD01-001〈ときのそら〉的推し技能「替換」在舞台上沒有應援時也能使用嗎？ 可以使用。 Q204（2024.10.04） Tentang SP Oshi Skill hSD01-001〈ときのそら〉 "じゃあ敵だね？": jika tidak ada Center Holomen atau tidak ada Back Holomen di panggung lawan, apakah SP Oshi Skill ini masih bisa digunakan? Ya, bisa digunakan. Untuk menyelesaikan efek sejauh mungkin, bagian "Tukar Center Holomen lawan dengan satu Back Holomen lawan." tidak akan diselesaikan, dan hanya bagian "Setelah itu, hingga akhir giliran ini, Arts Center Putih-mu +50." yang akan diselesaikan. Q203（2024.10.04） Tentang SP Oshi Skill hSD01-001〈ときのそら〉 "じゃあ敵だね？": saat menukar Center Holomen dan Back Holomen lawan, bolehkah memilih Holomen yang sedang istirahat? Ya, boleh. Q118（2024.09.21） Saat pemain giliran menggunakan SP Oshi Skill "じゃあ敵だね？", siapa yang memilih Back Holomen yang akan ditukar? Pemain yang menggunakan "じゃあ敵だね？" pada giliran tersebut. Q1（2024.09.21） Apakah Oshi Skill hSD01-001〈ときのそら〉 "リプレイスメント" bisa digunakan meskipun tidak ada Yell di panggung? Ya, bisa digunakan. Q204（2024.10.04） hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대 스테이지에 센터 홀로멘이 없거나 백 홀로멘이 없을 경우에도 이 SP 오시 스킬을 사용할 수 있나요? 네, 사용할 수 있습니다. 가능한 범위에서 효과를 해결하기 때문에 「상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다.」 부분은 해결하지 않고, 「그 후, 이번 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50.」 부분만 해결합니다. Q203（2024.10.04） hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대의 센터 홀로멘과 백 홀로멘을 교대시킬 때 휴식 중인 홀로멘을 선택할 수 있나요? 네, 가능합니다. Q118（2024.09.21） 턴 플레이어가 SP 오시 스킬 「그럼 적이네?」를 사용했을 때, 교대시킬 백 홀로멘을 선택하는 것은 어느 플레이어인가요? 「그럼 적이네?」를 사용한 턴 플레이어입니다. Q1（2024.09.21） hSD01-001〈ときのそら〉의 오시 스킬 「리플레이스먼트」는 스테이지에 에일이 없어도 사용할 수 있나요? 네, 사용할 수 있습니다. Q204（2024.10.04） เกี่ยวกับ SP 推しスキル 「งั้นเป็นศัตรูสิ?」 ของ hSD01-001〈ときのそら〉 ถ้าฝั่งตรงข้ามไม่มี センターホロメン บนสเตจ หรืไม่มี バックホロメン จะสามารถใช้สกิลนี้ได้ไหม ได้ สามารถใช้ได้ ในส่วนของการพยายามแก้ผลให้มากที่สุด ถ้าส่วนที่ว่า “สลับ センターホロメン ของฝ่ายตรงข้าม กับ バックホロメン 1 คน” ไม่สามารถแก้ได้ จะข้ามส่วนนั้นไป และแก้เฉพาะส่วนที่ว่า “จากนั้น ในช่วงเทิร์นนี้ アーツ ของ 白センター ホロメン ของตัวเอง +50” Q203（2024.10.04） เกี่ยวกับ SP 推しスキル 「งั้นเป็นศัตรูสิ?」 ของ hSD01-001〈ときのそら〉 เมื่อต้องสลับ センターホロメン กับ バックホロメン ของฝ่ายตรงข้าม สามารถเลือก ホロメン ที่อยู่ในสถานะพัก (お休み) ได้หรือไม่ ได้ สามารถเลือกได้ Q118（2024.09.21） เมื่อผู้เล่นที่กำลังเป็นเทิร์นใช้ SP 推しスキル 「งั้นเป็นศัตรูสิ?」 ผู้เล่นคนไหนเป็นคนเลือก バックホロメン ที่จะถูกสลับ ผู้เล่นที่ใช้ 「งั้นเป็นศัตรูสิ?」 ในเทิร์นนั้น เป็นผู้เลือก Q1（2024.09.21） เกี่ยวกับ 推しスキル 「Replacement」 ของ hSD01-001〈ときのそら〉 ถ้าบนสเตจไม่มี エール จะยังใช้สกิลนี้ได้ไหม ได้ สามารถใช้ได้ Q204（2024.10.04） Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, si el oponente no tiene un Holomen central o no tiene Holomen de respaldo, ¿puedo usar esta habilidad SP Oshi Skill? Sí, puedes usarla. Para resolver el efecto tanto como sea posible, la parte de “Intercambia el Holomen central y un Holomen de respaldo del oponente” no se resuelve, y solo se resuelve la parte “Luego, durante este turno, los Artes de tu Holomen central blanco obtienen +50.” Q203（2024.10.04） Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, cuando intercambias el Holomen central y el Holomen de respaldo del oponente, ¿puedes elegir un Holomen que esté descansando? Sí, puedes hacerlo. Q118（2024.09.21） Cuando el jugador del turno usa la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?”, ¿quién elige al Holomen de respaldo que se intercambiará? Lo elige el jugador del turno que usó “¿Entonces eres mi enemigo?”. Q1（2024.09.21） ¿Se puede usar la habilidad Oshi Skill “Reemplazo” de hSD01-001〈ときのそら〉 incluso si no hay cartas de Apoyo en el Escenario? Sí, puedes usarla.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2', 'hSD01-002', 'oshiCharacter', 'OSR', NULL, 'hSD01/hSD01-002_OSR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-002_OSR.png', NULL, 6, NULL, NULL, 'Hachi', 'AZKi', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["green"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"AZKi","oshi_skill":{"effect":"[Once per turn] Usable when rolling a die for the ability of your holomem: Declare 1 die result number, and treat the next result rolled as the declared number.","name":"A Map in My Left Hand","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Send any number of Cheer from your Archive to 1 of your green holomem.","name":"A Mic in My Right Hand","timing":"Once per game"}},"es":{"name":"AZKi","oshi_skill":{"effect":"[Una vez por turno] Puedes usar esto cuando una habilidad de tus holomen te haga tirar un dado: declara 1 resultado de dado, y el próximo resultado se trata como el resultado declarado.","name":"Mapa en la mano izquierda","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Envía cualquier cantidad de Cheers de tu archivo a 1 de tus holomen verdes.","name":"Micrófono en la mano derecha","timing":"Una vez por partida"}},"id":{"name":"AZKi","oshi_skill":{"effect":"[Sekali per giliran] Dapat digunakan saat melempar dadu dengan kemampuan holomen milikmu: nyatakan 1 angka hasil dadu, lalu anggap hasil berikutnya sebagai angka yang dinyatakan.","name":"Peta di Tangan Kiri","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Kirim sejumlah berapa pun Cheer dari arsipmu ke 1 holomen hijau milikmu.","name":"Mik di Tangan Kanan","timing":"Sekali per permainan"}},"ja":{"name":"AZKi","oshi_skill":{"effect":"[ターンに1回]自分のホロメンの能力でサイコロを振る時に使える:サイコロの目の数１つを宣言し、次に出る目の数を宣言した目として扱う。","name":"左手に地図","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のアーカイブのエールを自分の緑ホロメン1人に好きな枚数送る。","name":"右手にマイク","timing":"ゲームに1回"}},"ko":{"name":"AZKi","oshi_skill":{"effect":"[턴에 1번]자신의 홀로멘의 능력으로 주사위를 굴릴 때 사용할 수 있다: 주사위 눈 숫자 1개를 선언하고 다음에 나오는 눈 숫자를 선언한 눈으로 취급한다.","name":"왼손엔 지도","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 아카이브의 에일을 자신의 초록 홀로멘 1명에게 원하는 매수 보낸다.","name":"오른손엔 마이크","timing":"게임에 1번"}},"tc":{"name":"AZKi","oshi_skill":{"effect":"[每回合1次]可在因自己的holomen的能力而擲骰子時使用：宣告1個骰子點數，下一次擲出的點數視為所宣告的點數。","name":"左手拿地圖","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]將自己存檔區中的應援任意張數送給自己的1名綠色holomen。","name":"右手持麥克風","timing":"每場對戰1次"}},"th":{"name":"AZKi","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ใช้ได้เมื่อความสามารถของโฮโลเมนของคุณทอยลูกเต๋า: ประกาศแต้มของลูกเต๋า 1 ค่า และให้ผลลูกถัดไปที่ออกมาถือเป็นค่าที่ประกาศ","name":"มือถือแผนที่ไว้ในมือซ้าย","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ส่งเยลจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนสีเขียวของคุณ 1 คน ได้ตามจำนวนที่ต้องการ","name":"มือถือไมค์ไว้ในมือขวา","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{"en":[{"answer":"Yes, you can.","question":"When your Oshi Holomem is hSD01-002〈AZKi〉 and your Holomem is taking damage, you activate the Gift “V.7” of hBP01-027〈ベスティア・ゼータ〉. In this case, can you declare the die result using hSD01-002〈AZKi〉’s Oshi Skill “左手に地図”?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221 (2024.10.23)"},{"answer":"Yes, it can be used.","question":"Can hSD01-002〈AZKi〉''s SP Oshi skill ''A Mic in My Right Hand'' be used even if there is no cheer in the archive?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002: AZKi]"},"title":"Q2（September 21, 2024）"}],"es":[{"answer":"Sí, puedes hacerlo.","question":"Si tu Holomen favorito es hSD01-002〈AZKi〉 y cuando tu Holomen recibe daño usas el regalo “V.7” de hBP01-027〈ベスティア・ゼータ〉, ¿puedes declarar el resultado del dado usando la habilidad favorita “左手に地図” de hSD01-002〈AZKi〉?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"Sí, se puede usar.","question":"¿Se puede usar la habilidad SP 推し de hSD01-002〈AZKi〉 “Micrófono en la mano derecha” aunque no haya cartas de Ánimo en el Archivo?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"P2（2024.09.21）"}],"id":[{"answer":"Ya, bisa.","question":"Saat holomen oshimu adalah hSD01-002〈AZKi〉, dan holomen-mu menerima damage, kamu menggunakan Gift “V.7” dari hBP01-027〈ベスティア・ゼータ〉. Dalam kasus ini, apakah kamu dapat mendeklarasikan angka hasil dari skill oshimu “左手に地図” dari hSD01-002〈AZKi〉?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"Ya, bisa digunakan.","question":"Apakah SP oshi skill hSD01-002〈AZKi〉 \"右手にマイク\" bisa digunakan meskipun tidak ada Eru di Arsip?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"ja":[{"answer":"はい、できます。","question":"自分の推しホロメンがhSD01-002〈AZKi〉で、自分のホロメンがダメージを受ける時、hBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用しました。この場合、hSD01-002〈AZKi〉の推しスキル「左手に地図」を使用して出る目の数を宣言することはできますか。","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"はい、使用できます。","question":"hSD01-002〈AZKi〉のSP推しスキル「右手にマイク」はアーカイブにエールが無くても使用できますか？","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"ko":[{"answer":"네, 가능합니다.","question":"자신의 오시 홀로멘이 hSD01-002〈AZKi〉이고, 자신의 홀로멘이 피해를 받을 때 hBP01-027〈베스티아・제타〉의 선물 ‘V.7’을 사용했습니다. 이 경우, hSD01-002〈AZKi〉의 오시 스킬 ‘왼손에 지도’를 사용해 나올 눈을 선언할 수 있나요?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"네, 사용할 수 있습니다.","question":"hSD01-002〈AZKi〉의 SP 오시 스킬 ‘오른손에 마이크’는 아카이브에 응원이 없어도 사용할 수 있나요?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"tc":[{"answer":"是的，可以。","question":"當自己的推Holomen是hSD01-002〈AZKi〉，並在自己的Holomen要受到傷害時，使用了hBP01-027〈ベスティア・ゼータ〉的禮物「V.7」。在這種情況下，能否宣告使用hSD01-002〈AZKi〉的推技能「左手拿地圖」所要擲出的點數？","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"可以使用。","question":"hSD01-002〈AZKi〉的SP推し技能「右手握著麥克風」在檔案區域中沒有應援時也能使用嗎？","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"th":[{"answer":"ได้ สามารถทำได้","question":"เมื่อโฮโลเม็มโอชิของตัวเองคือ hSD01-002〈AZKi〉 และเมื่อโฮโลเม็มของตัวเองได้รับความเสียหาย ได้ใช้กิฟต์ “V.7” ของ hBP01-027〈ベスティア・ゼータ〉 ในกรณีนี้สามารถใช้สกิลโอชิ “左手に地図” ของ hSD01-002〈AZKi〉 เพื่อประกาศผลลูกเต๋าได้หรือไม่?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"ใช่ ใช้ได้","question":"สกิล SP Oshi ของ hSD01-002〈AZKi〉 「มือถือไมค์ไว้ในมือขวา」 สามารถใช้งานได้แม้ในกรณีที่อาร์ไคฟ์ไม่มีไอเยลหรือไม่","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}]}', '84fdf565a5f2ed8e17963203478868ec9ccb7e696e4b4eb3e068e9f84a93f668', 'b3166603d4a2af911fb503c221e77e2e399b3f80096d7bb66792c5c19ca516ae', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('green', '2');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '2');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (2, 'hSD01-002', 'hSD01-002 Hachi AZKi 左手に地図 [ターンに1回]自分のホロメンの能力でサイコロを振る時に使える:サイコロの目の数１つを宣言し、次に出る目の数を宣言した目として扱う。 右手にマイク [ゲームに1回]自分のアーカイブのエールを自分の緑ホロメン1人に好きな枚数送る。 AZKi A Map in My Left Hand [Once per turn] Usable when rolling a die for the ability of your holomem: Declare 1 die result number, and treat the next result rolled as the declared number. A Mic in My Right Hand [Once per game] Send any number of Cheer from your Archive to 1 of your green holomem. AZKi 左手拿地圖 [每回合1次]可在因自己的holomen的能力而擲骰子時使用：宣告1個骰子點數，下一次擲出的點數視為所宣告的點數。 右手持麥克風 [每場對戰1次]將自己存檔區中的應援任意張數送給自己的1名綠色holomen。 AZKi Peta di Tangan Kiri [Sekali per giliran] Dapat digunakan saat melempar dadu dengan kemampuan holomen milikmu: nyatakan 1 angka hasil dadu, lalu anggap hasil berikutnya sebagai angka yang dinyatakan. Mik di Tangan Kanan [Sekali per permainan] Kirim sejumlah berapa pun Cheer dari arsipmu ke 1 holomen hijau milikmu. AZKi 왼손엔 지도 [턴에 1번]자신의 홀로멘의 능력으로 주사위를 굴릴 때 사용할 수 있다: 주사위 눈 숫자 1개를 선언하고 다음에 나오는 눈 숫자를 선언한 눈으로 취급한다. 오른손엔 마이크 [게임에 1번]자신의 아카이브의 에일을 자신의 초록 홀로멘 1명에게 원하는 매수 보낸다. AZKi มือถือแผนที่ไว้ในมือซ้าย [ใช้ได้ 1 ครั้งต่อเทิร์น] ใช้ได้เมื่อความสามารถของโฮโลเมนของคุณทอยลูกเต๋า: ประกาศแต้มของลูกเต๋า 1 ค่า และให้ผลลูกถัดไปที่ออกมาถือเป็นค่าที่ประกาศ มือถือไมค์ไว้ในมือขวา [ใช้ได้ 1 ครั้งต่อเกม] ส่งเยลจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนสีเขียวของคุณ 1 คน ได้ตามจำนวนที่ต้องการ AZKi Mapa en la mano izquierda [Una vez por turno] Puedes usar esto cuando una habilidad de tus holomen te haga tirar un dado: declara 1 resultado de dado, y el próximo resultado se trata como el resultado declarado. Micrófono en la mano derecha [Una vez por partida] Envía cualquier cantidad de Cheers de tu archivo a 1 de tus holomen verdes.', 'Q221（2024.10.23） 自分の推しホロメンがhSD01-002〈AZKi〉で、自分のホロメンがダメージを受ける時、hBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用しました。この場合、hSD01-002〈AZKi〉の推しスキル「左手に地図」を使用して出る目の数を宣言することはできますか。 はい、できます。 Q2（2024.09.21） hSD01-002〈AZKi〉のSP推しスキル「右手にマイク」はアーカイブにエールが無くても使用できますか？ はい、使用できます。 Q221 (2024.10.23) When your Oshi Holomem is hSD01-002〈AZKi〉 and your Holomem is taking damage, you activate the Gift “V.7” of hBP01-027〈ベスティア・ゼータ〉. In this case, can you declare the die result using hSD01-002〈AZKi〉’s Oshi Skill “左手に地図”? Yes, you can. Q2（September 21, 2024） Can hSD01-002〈AZKi〉''s SP Oshi skill ''A Mic in My Right Hand'' be used even if there is no cheer in the archive? Yes, it can be used. Q221（2024.10.23） 當自己的推Holomen是hSD01-002〈AZKi〉，並在自己的Holomen要受到傷害時，使用了hBP01-027〈ベスティア・ゼータ〉的禮物「V.7」。在這種情況下，能否宣告使用hSD01-002〈AZKi〉的推技能「左手拿地圖」所要擲出的點數？ 是的，可以。 Q2（2024.09.21） hSD01-002〈AZKi〉的SP推し技能「右手握著麥克風」在檔案區域中沒有應援時也能使用嗎？ 可以使用。 Q221（2024.10.23） Saat holomen oshimu adalah hSD01-002〈AZKi〉, dan holomen-mu menerima damage, kamu menggunakan Gift “V.7” dari hBP01-027〈ベスティア・ゼータ〉. Dalam kasus ini, apakah kamu dapat mendeklarasikan angka hasil dari skill oshimu “左手に地図” dari hSD01-002〈AZKi〉? Ya, bisa. Q2（2024.09.21） Apakah SP oshi skill hSD01-002〈AZKi〉 "右手にマイク" bisa digunakan meskipun tidak ada Eru di Arsip? Ya, bisa digunakan. Q221（2024.10.23） 자신의 오시 홀로멘이 hSD01-002〈AZKi〉이고, 자신의 홀로멘이 피해를 받을 때 hBP01-027〈베스티아・제타〉의 선물 ‘V.7’을 사용했습니다. 이 경우, hSD01-002〈AZKi〉의 오시 스킬 ‘왼손에 지도’를 사용해 나올 눈을 선언할 수 있나요? 네, 가능합니다. Q2（2024.09.21） hSD01-002〈AZKi〉의 SP 오시 스킬 ‘오른손에 마이크’는 아카이브에 응원이 없어도 사용할 수 있나요? 네, 사용할 수 있습니다. Q221（2024.10.23） เมื่อโฮโลเม็มโอชิของตัวเองคือ hSD01-002〈AZKi〉 และเมื่อโฮโลเม็มของตัวเองได้รับความเสียหาย ได้ใช้กิฟต์ “V.7” ของ hBP01-027〈ベスティア・ゼータ〉 ในกรณีนี้สามารถใช้สกิลโอชิ “左手に地図” ของ hSD01-002〈AZKi〉 เพื่อประกาศผลลูกเต๋าได้หรือไม่? ได้ สามารถทำได้ Q2（2024.09.21） สกิล SP Oshi ของ hSD01-002〈AZKi〉 「มือถือไมค์ไว้ในมือขวา」 สามารถใช้งานได้แม้ในกรณีที่อาร์ไคฟ์ไม่มีไอเยลหรือไม่ ใช่ ใช้ได้ Q221（2024.10.23） Si tu Holomen favorito es hSD01-002〈AZKi〉 y cuando tu Holomen recibe daño usas el regalo “V.7” de hBP01-027〈ベスティア・ゼータ〉, ¿puedes declarar el resultado del dado usando la habilidad favorita “左手に地図” de hSD01-002〈AZKi〉? Sí, puedes hacerlo. P2（2024.09.21） ¿Se puede usar la habilidad SP 推し de hSD01-002〈AZKi〉 “Micrófono en la mano derecha” aunque no haya cartas de Ánimo en el Archivo? Sí, se puede usar.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('6', 'hSD01-006', 'buzzCharacter', 'RR', 'first', 'hSD01/hSD01-006_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-006_RR.png', 240, NULL, 2, '["null","null"]', 'I☆LA', 'ときのそら', '{"arts":[{"cost_types":["white","null"],"damage":50},{"cost_types":["white","green","null"],"damage":60,"is_plus":true}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["white"],"translations":{"en":{"arts":[{"name":"Dream Live"},{"effect":"If there is a holomem 〈AZKi〉 on your Stage, this Art gets +50.","name":"SorAZ Sympathy"}],"extra":"When this holomem is Downed, your Life -2.","name":"Tokino Sora","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"Dream Live"},{"effect":"Si hay un 〈AZKi〉 de holomen en tu Escenario, este Arte +50.","name":"Simpatía SorAZ"}],"extra":"Cuando este holomen quede abatido, tu vida -2","name":"Tokino Sora","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Dream Live"},{"effect":"Jika ada 〈AZKi〉 holomen di Stage milikmu, Arts ini +50.","name":"SorAZ Sympathy"}],"extra":"Saat Holomen ini Down, Life milikmu -2","name":"Tokino Sora","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"ドリームライブ"},{"effect":"自分のステージにホロメンの〈AZKi〉がいる時、このアーツ+50。","name":"SorAZ シンパシー"}],"extra":"このホロメンがダウンした時、自分のライフ-2","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"드림 라이브"},{"effect":"자신의 스테이지에 홀로멘의 〈AZKi〉가 있을 때, 이 아츠 +50.","name":"SorAZ 심퍼시"}],"extra":"이 홀로멤이 다운되었을 때, 자신의 라이프 -2","name":"토키노 소라","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"夢幻演唱會"},{"effect":"當自己的舞台上有Holomen的〈AZKi〉時，此藝術+50。","name":"SorAZ Sympathy"}],"extra":"此Holo成員倒下時，自己的生命值-2","name":"時乃空","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"ดรีมไลฟ์"},{"effect":"ขณะที่บนสเตจของคุณมี 〈AZKi〉 ของโฮโลเมมอยู่ ศิลปะนี้ +50","name":"SorAZ ซิมพาธี"}],"extra":"เมื่อโฮโลเมมเบอร์นี้ดาวน์ ชีวิตของคุณ -2","name":"โตกิโนะ โซระ","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{"en":[{"answer":"Yes, it receives +50. Even if the card name doesn’t directly match, if there’s an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition.","question":"For hSD01-006〈ときのそら〉’s Art “SorAZ Sympathy,” does the Art receive +50 if I have hSD01-013〈SorAZ〉 among my Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5 (2024.09.21)"},{"answer":"Yes, the condition is met. Even if there isn’t a card with that exact name, since its Extra states “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” the condition is fulfilled.","question":"For hSD01-006〈ときのそら〉''s Arts ''SorAZ シンパシー'', does the condition “If there is a Holomen〈AZKi〉on your Stage” also count if hSD01-013〈SorAZ〉is on your Stage?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4 (2024.09.21)"}],"es":[{"answer":"Sí, recibe +50. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición.","question":"En el Arte “SorAZ Sympathy” de hSD01-006〈ときのそら〉, ¿recibe igualmente “este Arte +50.” si tengo hSD01-013〈SorAZ〉 entre mis Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"Sí, se cumple. Aunque el nombre de la carta no coincida exactamente, en la sección de Extra se indica “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, por lo tanto cumple la condición.","question":"En el arte “SorAZ シンパシー” de hSD01-006〈ときのそら〉, la condición “Cuando tengas a la Holomen〈AZKi〉en tu escenario” ¿también se cumple si tienes a hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"id":[{"answer":"Ya, menjadi +50. Walaupun tidak ada kartu dengan nama yang sama, jika ada kemampuan ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Apakah arts “SorAZ Sympathy” dari hSD01-006〈ときのそら〉menjadi +50 saat aku memiliki hSD01-013〈SorAZ〉di antara Holomen-ku?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"Ya, kondisi terpenuhi. Bahkan jika tidak ada nama kartu yang persis sesuai, karena di extra tertulis “holomen ini juga diperlakukan sebagai〈ときのそら〉〈AZKi〉”, jadi kondisi itu terpenuhi.","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ Sympathy」の「自分のステージにホロメンの〈AZKi〉がいる時」は、hSD01-013〈SorAZ〉がいる場合でも条件を満たしますか？","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"ja":[{"answer":"はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"はい、条件を満たします。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」と書かれているため、条件を満たします。","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」の「自分のステージにホロメンの〈AZKi〉がいる時」は、hSD01-013〈SorAZ〉がいる場合でも条件を満たしますか？","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"ko":[{"answer":"네, +50이 됩니다. 카드명에 해당 카드가 없더라도 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」와 같이 특정 카드명으로 취급되는 카드가 있다면 조건을 만족합니다.","question":"hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」는 자신의 홀로멘에 hSD01-013〈SorAZ〉가 있을 때에도 ''이 아츠 +50.''이 되나요?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"네, 조건을 충족합니다. 카드명에 해당 카드가 없더라도, 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」라고 적혀 있기 때문에 조건을 충족합니다.","question":"hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」의 「자신의 스테이지에 홀로멘 〈AZKi〉가 있을 때」는, hSD01-013〈SorAZ〉가 있는 경우에도 조건을 충족합니까?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"tc":[{"answer":"會，會增加+50。即使卡名不一致，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似效果，便能滿足條件。","question":"hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」，當自己場上有hSD01-013〈SorAZ〉時，也會使「此藝術+50」嗎？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"是的，可以滿足條件。即使卡牌名稱中沒有對應的卡牌，因為額外能力中寫有「此Holomen同時視為〈ときのそら〉〈AZKi〉」，所以能滿足條件。","question":"hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」中，「當自己的舞台上有Holomen〈AZKi〉時」這個條件，在有hSD01-013〈SorAZ〉時也能滿足嗎？","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"th":[{"answer":"ได้ครับ/ค่ะ จะได้รับ +50 แม้จะไม่มีการกล่าวถึงชื่อการ์ดที่ตรงกันในชื่อการ์ด แต่ถ้ามีความสามารถพิเศษในเอ็กซ์ตราที่ระบุว่า \"โฮโลเมนนี้ถือเป็น〈ときのそら〉และ〈AZKi〉ด้วย\" แบบนี้ ก็ถือว่าตรงตามเงื่อนไข","question":"อาร์ท \"SorAZ シンパシー\" ของ hSD01-006〈ときのそら〉 จะได้รับ \"+50\" ถ้าในฝั่งของตัวเองมี hSD01-013〈SorAZ〉 อยู่หรือไม่?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"ได้ครับ/ค่ะ เงื่อนไขถือว่าเป็นจริง เพราะแม้จะไม่มีชื่อการ์ดตรงกัน แต่ถ้าในเอ็กซ์ตราระบุว่า \"โฮโลเมนนี้ถือเป็น〈ときのそら〉และ〈AZKi〉ด้วย\" ก็ถือว่าตรงตามเงื่อนไข","question":"เงื่อนไข \"เมื่อบนสเตจของตัวเองมีโฮโลเมน〈AZKi〉\" ของอาร์ท \"SorAZ シンパシー\" บน hSD01-006〈ときのそら〉 จะยังถือว่าเป็นจริงถ้ามี hSD01-013〈SorAZ〉 อยู่หรือไม่?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}]}', 'e9755b77fbb8e4e360897ccace4a2dabc411a6f4ed2d2d319ec768aae445af15', 'f9deaaa0116df0fafcf9c8a01da09468399784a5ef89df7e7bdecb294436eb4e', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white', '6');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '6');
INSERT INTO card_tags (tag, card_id) VALUES ('JP', '6');
INSERT INTO card_tags (tag, card_id) VALUES ('0期生', '6');
INSERT INTO card_tags (tag, card_id) VALUES ('歌', '6');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (6, 'hSD01-006', 'hSD01-006 I☆LA JP 0期生 歌 ときのそら #JP #0期生 #歌 このホロメンがダウンした時、自分のライフ-2 ドリームライブ SorAZ シンパシー 自分のステージにホロメンの〈AZKi〉がいる時、このアーツ+50。 Tokino Sora #JP #0th Gen #Singing When this holomem is Downed, your Life -2. Dream Live SorAZ Sympathy If there is a holomem 〈AZKi〉 on your Stage, this Art gets +50. 時乃空 #JP #0期生 #歌唱 此Holo成員倒下時，自己的生命值-2 夢幻演唱會 SorAZ Sympathy 當自己的舞台上有Holomen的〈AZKi〉時，此藝術+50。 Tokino Sora #JP #Gen 0 #Menyanyi Saat Holomen ini Down, Life milikmu -2 Dream Live SorAZ Sympathy Jika ada 〈AZKi〉 holomen di Stage milikmu, Arts ini +50. 토키노 소라 #JP #0기생 #노래 이 홀로멤이 다운되었을 때, 자신의 라이프 -2 드림 라이브 SorAZ 심퍼시 자신의 스테이지에 홀로멘의 〈AZKi〉가 있을 때, 이 아츠 +50. โตกิโนะ โซระ #JP #รุ่น 0 #เพลง เมื่อโฮโลเมมเบอร์นี้ดาวน์ ชีวิตของคุณ -2 ดรีมไลฟ์ SorAZ ซิมพาธี ขณะที่บนสเตจของคุณมี 〈AZKi〉 ของโฮโลเมมอยู่ ศิลปะนี้ +50 Tokino Sora #JP #0th Gen #Singing Cuando este holomen quede abatido, tu vida -2 Dream Live Simpatía SorAZ Si hay un 〈AZKi〉 de holomen en tu Escenario, este Arte +50.', 'Q5（2024.09.21） hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？ はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。 Q4（2024.09.21） hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」の「自分のステージにホロメンの〈AZKi〉がいる時」は、hSD01-013〈SorAZ〉がいる場合でも条件を満たしますか？ はい、条件を満たします。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」と書かれているため、条件を満たします。 Q5 (2024.09.21) For hSD01-006〈ときのそら〉’s Art “SorAZ Sympathy,” does the Art receive +50 if I have hSD01-013〈SorAZ〉 among my Holomen? Yes, it receives +50. Even if the card name doesn’t directly match, if there’s an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition. Q4 (2024.09.21) For hSD01-006〈ときのそら〉''s Arts ''SorAZ シンパシー'', does the condition “If there is a Holomen〈AZKi〉on your Stage” also count if hSD01-013〈SorAZ〉is on your Stage? Yes, the condition is met. Even if there isn’t a card with that exact name, since its Extra states “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” the condition is fulfilled. Q5（2024.09.21） hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」，當自己場上有hSD01-013〈SorAZ〉時，也會使「此藝術+50」嗎？ 會，會增加+50。即使卡名不一致，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似效果，便能滿足條件。 Q4（2024.09.21） hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」中，「當自己的舞台上有Holomen〈AZKi〉時」這個條件，在有hSD01-013〈SorAZ〉時也能滿足嗎？ 是的，可以滿足條件。即使卡牌名稱中沒有對應的卡牌，因為額外能力中寫有「此Holomen同時視為〈ときのそら〉〈AZKi〉」，所以能滿足條件。 Q5（2024.09.21） Apakah arts “SorAZ Sympathy” dari hSD01-006〈ときのそら〉menjadi +50 saat aku memiliki hSD01-013〈SorAZ〉di antara Holomen-ku? Ya, menjadi +50. Walaupun tidak ada kartu dengan nama yang sama, jika ada kemampuan ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat. Q4（2024.09.21） hSD01-006〈ときのそら〉のアーツ「SorAZ Sympathy」の「自分のステージにホロメンの〈AZKi〉がいる時」は、hSD01-013〈SorAZ〉がいる場合でも条件を満たしますか？ Ya, kondisi terpenuhi. Bahkan jika tidak ada nama kartu yang persis sesuai, karena di extra tertulis “holomen ini juga diperlakukan sebagai〈ときのそら〉〈AZKi〉”, jadi kondisi itu terpenuhi. Q5（2024.09.21） hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」는 자신의 홀로멘에 hSD01-013〈SorAZ〉가 있을 때에도 ''이 아츠 +50.''이 되나요? 네, +50이 됩니다. 카드명에 해당 카드가 없더라도 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」와 같이 특정 카드명으로 취급되는 카드가 있다면 조건을 만족합니다. Q4（2024.09.21） hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」의 「자신의 스테이지에 홀로멘 〈AZKi〉가 있을 때」는, hSD01-013〈SorAZ〉가 있는 경우에도 조건을 충족합니까? 네, 조건을 충족합니다. 카드명에 해당 카드가 없더라도, 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」라고 적혀 있기 때문에 조건을 충족합니다. Q5（2024.09.21） อาร์ท "SorAZ シンパシー" ของ hSD01-006〈ときのそら〉 จะได้รับ "+50" ถ้าในฝั่งของตัวเองมี hSD01-013〈SorAZ〉 อยู่หรือไม่? ได้ครับ/ค่ะ จะได้รับ +50 แม้จะไม่มีการกล่าวถึงชื่อการ์ดที่ตรงกันในชื่อการ์ด แต่ถ้ามีความสามารถพิเศษในเอ็กซ์ตราที่ระบุว่า "โฮโลเมนนี้ถือเป็น〈ときのそら〉และ〈AZKi〉ด้วย" แบบนี้ ก็ถือว่าตรงตามเงื่อนไข Q4（2024.09.21） เงื่อนไข "เมื่อบนสเตจของตัวเองมีโฮโลเมน〈AZKi〉" ของอาร์ท "SorAZ シンパシー" บน hSD01-006〈ときのそら〉 จะยังถือว่าเป็นจริงถ้ามี hSD01-013〈SorAZ〉 อยู่หรือไม่? ได้ครับ/ค่ะ เงื่อนไขถือว่าเป็นจริง เพราะแม้จะไม่มีชื่อการ์ดตรงกัน แต่ถ้าในเอ็กซ์ตราระบุว่า "โฮโลเมนนี้ถือเป็น〈ときのそら〉และ〈AZKi〉ด้วย" ก็ถือว่าตรงตามเงื่อนไข Q5（2024.09.21） En el Arte “SorAZ Sympathy” de hSD01-006〈ときのそら〉, ¿recibe igualmente “este Arte +50.” si tengo hSD01-013〈SorAZ〉 entre mis Holomen? Sí, recibe +50. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición. Q4（2024.09.21） En el arte “SorAZ シンパシー” de hSD01-006〈ときのそら〉, la condición “Cuando tengas a la Holomen〈AZKi〉en tu escenario” ¿también se cumple si tienes a hSD01-013〈SorAZ〉? Sí, se cumple. Aunque el nombre de la carta no coincida exactamente, en la sección de Extra se indica “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, por lo tanto cumple la condición.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('13', 'hSD01-013', 'character', 'R', 'first', 'hSD01/hSD01-013_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-013_R.png', 130, NULL, 1, '["null"]', '© 2023 Victor Entertainment.', 'SorAZ', '{"arts":[{"cost_types":["null","null"],"damage":50}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["white","green"],"translations":{"en":{"arts":[{"effect":"You may roll a six-sided die: If the result is odd, send the top card of your Cheer Deck to this holomem. If the result is even, draw 1 card.","name":"The Future I Want to Reach"}],"extra":"This holomem is also treated as 〈Tokino Sora〉 and 〈AZKi〉.","name":"SorAZ","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"effect":"Puedes lanzar 1 dado: si sale un número impar, envía la carta superior de tu mazo de Cheer a este holomen. Si sale un número par, roba 1 carta de tu mazo.","name":"El futuro que quiero alcanzar"}],"extra":"Este holomen también se considera como 〈Tokino Sora〉 y 〈AZKi〉","name":"SorAZ","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, kirim 1 kartu teratas dari deck Cheer-mu ke holomen ini. Jika hasilnya genap, ambil 1 kartu dari deck-mu.","name":"Masa Depan yang Ingin Kuraih"}],"extra":"Holomen ini juga diperlakukan sebagai 〈Tokino Sora〉〈AZKi〉","name":"SorAZ","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"effect":"サイコロを1回振れる:奇数の時、自分のエールデッキの上から1枚を、このホロメンに送る。偶数の時、自分のデッキを1枚引く。","name":"越えたい未来"}],"extra":"このホロメンは〈ときのそら〉〈AZKi〉としても扱う","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"주사위를 1번 굴릴 수 있다: 홀수라면, 자신의 에일 덱 위에서 1장을 이 홀로멘에게 보낸다. 짝수라면, 자신의 덱을 1장 뽑는다.","name":"넘고 싶은 미래"}],"extra":"이 홀로멤은 〈토키노 소라〉 〈AZKi〉로도 취급한다","name":"SorAZ","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"effect":"可擲1次骰子：為奇數時，將自己應援牌庫頂部1張卡送給這位Holo成員。為偶數時，抽1張自己的牌庫。","name":"想要跨越的未來"}],"extra":"此Holo成員也視為〈時乃空〉〈AZKi〉","name":"SorAZ","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้งได้: ถ้าเป็นเลขคี่ ส่งการ์ด 1 ใบจากบนสุดของเอิลเด็คของคุณไปยังโฮโลเมนนี้ ถ้าเป็นเลขคู่ จั่วเด็คของคุณ 1 ใบ","name":"อนาคตที่อยากก้าวข้ามไปให้ถึง"}],"extra":"โฮโลเมมเบอร์นี้ให้นับเป็น〈โตกิโนะ โซระ〉〈AZKi〉ได้ด้วย","name":"SorAZ","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{"en":[{"answer":"It means this card has the names 〈ときのそら〉, 〈AZKi〉, and 〈SorAZ〉.","question":"What does hSD01-013〈SorAZ〉’s extra ability “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉.” mean?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616 (2026.03.02)"},{"answer":"No, you cannot.","question":"When you have one hSD01-013〈SorAZ〉 and hBP07-068〈AZKi〉 performs a Collab, can you count hSD01-013〈SorAZ〉 as both 〈ときのそら〉 and 〈SorAZ〉 for the effect of the Collab Effect “The Path We’ve Walked Together”?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602 (2026.03.02)"},{"answer":"Yes, you can.","question":"When using hBP04-089〈ツートンカラーパソコン〉, I chose 〈ときのそら〉 and 〈フワワ・アビスガード〉 on my Stage as the two Holomen with different single colors. In this case, can I add hSD01-013〈SorAZ〉 and hBP03-050〈FUWAMOCO〉 to my hand as the 1st Holomen of the same colors as the chosen Holomen?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404 (2025.06.11)"},{"answer":"It refers to Holomen that each have only one color, and there are at least two of them with different colors. For example, hBP01-021〈ときのそら〉 has one color, while hSD01-013〈SorAZ〉 has two colors.","question":"In hBP04-089〈ツートンカラーパソコン〉, what does “a Holomen with a single color that differs from another color” mean?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402 (2025.06.11)"},{"answer":"Yes, you can.","question":"Can I use hBP02-078〈かなた建設〉 to add hSD01-013〈SorAZ〉 to my hand?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250 (2024.12.12)"},{"answer":"No, hBP01-124〈開拓者〉 is archived.","question":"If my hSD01-013〈SorAZ〉 with hBP01-124〈開拓者〉 attached Blooms into hBP01-023〈ときのそら〉, does hBP01-124〈開拓者〉 stay attached?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116 (2024.09.21)"},{"answer":"Yes, you can. Even if the card name doesn’t directly match, as long as there is a card with an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉”, it satisfies that condition.","question":"In hSD01-021〈First Gravity〉’s text, it says “Reveal any number of 〈ときのそら〉 and 〈AZKi〉 cards.” Can I reveal hSD01-013〈SorAZ〉 and add it to my hand?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17 (2024.09.21)"},{"answer":"Yes, both abilities will activate. Because hSD01-013〈SorAZ〉 is treated as 〈ときのそら〉 and 〈AZKi〉 due to its Extra, both Holomen names are considered to be on stage.","question":"If hSD01-013〈SorAZ〉 is in the center position and my hSD01-015〈Hakui Koyori〉 performs a Collab, will both Collab Effect abilities trigger?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13 (2024.09.21)"},{"answer":"Yes, it does.","question":"For hSD01-013〈SorAZ〉’s extra ability “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” does it apply even when it is not on the stage?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12 (2025.12.18)"},{"answer":"Yes, you can. After declaring the use of the Arts, resolve as much of the effect as possible based on the text, then apply the Arts damage.","question":"Can I use hSD01-013〈SorAZ〉’s Arts “Future I Want to Surpass” even if my deck or Cheer Deck has 0 cards?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11 (2024.09.21)"},{"answer":"Yes, you can. Even if you don’t have a Holomen with that specific card name, if a card in the Extra area states something like “This Holomen is also treated as 〈ときのそら〉〈AZKi〉,” it counts as fulfilling that condition.","question":"For hSD01-011〈AZKi〉’s Arts “SorAZ グラビティ”, if you don’t have 〈ときのそら〉 among your Holomen, can you still send the top card of your Yell deck to one of your Holomen if you have hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10 (2024.09.21)"},{"answer":"Yes, it receives +50. Even if the card name doesn’t directly match, if there’s an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition.","question":"For hSD01-006〈ときのそら〉’s Art “SorAZ Sympathy,” does the Art receive +50 if I have hSD01-013〈SorAZ〉 among my Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5 (2024.09.21)"}],"es":[{"answer":"Significa que posee los nombres de carta〈ときのそら〉,〈AZKi〉y〈SorAZ〉.","question":"¿Qué significa la habilidad extra de hSD01-013〈SorAZ〉『Este Holomen también se considera como〈ときのそら〉y〈AZKi〉』?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"No, no se puede.","question":"Cuando tienes un hSD01-013〈SorAZ〉 en tu campo y hBP07-068〈AZKi〉 realiza una colaboración, ¿en este caso se puede contar a hSD01-013〈SorAZ〉 como dos personas, 〈ときのそら〉 y 〈SorAZ〉, para la habilidad del efecto de colaboración «El camino recorrido juntos»?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"Sí, puedes hacerlo.","question":"Usando hBP04-089〈ツートンカラーパソコン〉, elegí como holomen de colores diferentes en mi escenario a 〈ときのそら〉 y 〈フワワ・アビスガード〉. En este caso, ¿puedo añadir a mi mano a hSD01-013〈SorAZ〉 y a hBP03-050〈FUWAMOCO〉 como holomen 1st del mismo color que los elegidos?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Significa que esos Holomen tienen un solo color cada uno, y que hay al menos dos con colores distintos. Por ejemplo, hBP01-021〈ときのそら〉 tiene un solo color, mientras que hSD01-013〈SorAZ〉 tiene dos colores.","question":"¿Qué significa “Holomen de un solo color y de distinto color” en el texto de hBP04-089〈ツートンカラーパソコン〉?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"Sí, es posible.","question":"¿Puedo añadir hSD01-013〈SorAZ〉 a mi mano usando hBP02-078〈かなた建設〉?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"No, hBP01-124〈開拓者〉se archiva.","question":"Si tu hSD01-013〈SorAZ〉con hBP01-124〈開拓者〉adjunto hace Bloom hacia hBP01-023〈ときのそら〉, ¿permanece adjunto hBP01-124〈開拓者〉?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"Sí, puedes. Aunque no exista una carta con ese nombre exacto, si en el Extra hay una carta que indique algo como «esta Holomen también cuenta como 〈ときのそら〉 y 〈AZKi〉», entonces cumple con las condiciones.","question":"En el texto de hSD01-021〈First Gravity〉 dice «puedes revelar cualquier número de 〈ときのそら〉 y 〈AZKi〉». ¿Puedo revelar y añadir a la mano una hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Sí, se activan ambas habilidades. hSD01-013〈SorAZ〉, debido a su extra, se trata como 〈ときのそら〉 y 〈AZKi〉, por lo que se considera que ambos nombres de Holomen están en el escenario.","question":"Si tienes a hSD01-013〈SorAZ〉 en la posición central, y haces una colaboración con tu hSD01-015〈博衣こより〉, ¿se activan ambas habilidades del efecto de colaboración?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"Sí, se aplica.","question":"¿La habilidad extra “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉” de hSD01-013〈SorAZ〉 aplica también cuando no está en el escenario?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"Sí, se puede usar. Después de declarar el uso del arte, se resuelve el efecto del texto lo más posible y luego se aplica el daño del arte.","question":"¿Se puede usar el arte『Futuro que quiero superar』de hSD01-013〈SorAZ〉incluso si tu mazo o tu mazo de ánimo tienen 0 cartas?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"Sí, puedes hacerlo. Incluso si no hay una carta con ese nombre exacto, si existe una carta en el Extra que diga algo como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, esa carta cumple con la condición.","question":"En hSD01-011〈AZKi〉, la Artes «SorAZ グラビティ» te permite enviar la carta superior de tu mazo de Aplausos a uno de tus Holomen si tienes a 〈ときのそら〉 en tu escenario. ¿Puedes hacerlo también si no tienes a 〈ときのそら〉 pero sí a hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"Sí, recibe +50. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición.","question":"En el Arte “SorAZ Sympathy” de hSD01-006〈ときのそら〉, ¿recibe igualmente “este Arte +50.” si tengo hSD01-013〈SorAZ〉 entre mis Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"id":[{"answer":"Artinya kartu ini memiliki nama sebagai〈ときのそら〉,〈AZKi〉dan〈SorAZ〉.","question":"Apa arti dari kemampuan ekstra hSD01-013〈SorAZ〉「Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉」?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"Tidak, tidak bisa.","question":"Saat kamu memiliki satu〈SorAZ〉hSD01-013 di lapangan, lalu〈AZKi〉hBP07-068 melakukan Kolaborasi. Dalam hal ini, apakah efek kolaborasi “Jejak yang telah kita lalui bersama” dapat menghitung〈SorAZ〉sebagai dua orang yaitu〈ときのそら〉dan〈SorAZ〉?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"Ya, boleh menambahkannya.","question":"Saat menggunakan hBP04-089〈ツートンカラーパソコン〉, saya memilih 〈ときのそら〉 dan 〈フワワ・アビスガード〉 sebagai dua Holomen di panggung saya yang masing-masing hanya memiliki 1 warna dan warnanya berbeda. Dalam kasus ini, apakah saya bisa menambah hSD01-013〈SorAZ〉 dan hBP03-050〈FUWAMOCO〉 sebagai 1st Holomen yang warnanya sama dengan Holomen yang dipilih ke tangan saya?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Maksudnya Holomen yang dimaksud hanya memiliki satu warna saja, dan ada setidaknya dua Holomen seperti itu. Sebagai contoh, hBP01-021〈ときのそら〉 hanya memiliki satu warna, sedangkan hSD01-013〈SorAZ〉 memiliki dua warna.","question":"Apa arti dari “Holomen yang memiliki tepat 1 warna dan warnanya berbeda” pada hBP04-089〈ツートンカラーパソコン〉?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"Ya, bisa.","question":"hBP02-078〈かなた建設〉を使用して、hSD01-013〈SorAZ〉を手札に加えることができますか？","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"Tidak,〈開拓者〉hBP01-124 akan diarsipkan.","question":"Jika〈SorAZ〉hSD01-013 milikku yang memiliki〈開拓者〉hBP01-124 melakukan Bloom menjadi〈ときのそら〉hBP01-023, apakah〈開拓者〉tetap terpasang?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"Ya, bisa. Walaupun tidak ada kartu dengan nama yang sama, jika ada kartu dengan efek ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Pada hSD01-021〈First Gravity〉tertulis “perlihatkan sebanyak yang kamu mau kartu〈ときのそら〉dan〈AZKi〉”. Apakah aku bisa memperlihatkan hSD01-013〈SorAZ〉dan menambahkannya ke tangan?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Ya, keduanya akan aktif. Karena〈SorAZ〉hSD01-013 dianggap juga sebagai〈ときのそら〉dan〈AZKi〉 berkat kemampuan ekstra, maka dianggap Holomen dengan kedua nama tersebut ada di panggung.","question":"Jika〈SorAZ〉hSD01-013 ada di posisi tengah, lalu〈博衣こより〉hSD01-015 melakukan kolaborasi, apakah kedua kemampuan kolaborasi akan aktif?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"Ya, berlaku.","question":"Apakah kemampuan ekstra〈SorAZ〉hSD01-013 “Holomen ini juga dianggap sebagai〈ときのそら〉dan〈AZKi〉” juga berlaku di luar panggung?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"Ya, bisa digunakan. Setelah menyatakan penggunaan Art, selesaikan efek yang memungkinkan sebanyak mungkin, lalu berikan damage Art.","question":"Apakah aku bisa menggunakan Art〈Masa Depan yang Ingin Ku Lewati〉 milik〈SorAZ〉hSD01-013 walaupun dek atau dek sorakan-ku kosong?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"Ya, dapat. Bahkan jika nama kartu yang dimaksud tidak secara eksplisit ada pada nama kartu, jika ada kartu di zona ekstra yang memperlakukan kartu itu sebagai nama tertentu seperti “anggota Holomen ini juga diperlakukan sebagai〈ときのそら〉〈AZKi〉”, maka syarat itu terpenuhi.","question":"Apakah arts “SorAZ グラビティ” dari hSD01-011〈AZKi〉 dapat mengirim 1 kartu teratas dari dek Ail saya ke anggota Holomen saya jika tidak ada〈ときのそら〉 di Holomen saya tetapi ada hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"Ya, menjadi +50. Walaupun tidak ada kartu dengan nama yang sama, jika ada kemampuan ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Apakah arts “SorAZ Sympathy” dari hSD01-006〈ときのそら〉menjadi +50 saat aku memiliki hSD01-013〈SorAZ〉di antara Holomen-ku?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"ja":[{"answer":"カード名として、〈ときのそら〉、〈AZKi〉、〈SorAZ〉を持つことを指します。","question":"hSD01-013〈SorAZ〉のエクストラ能力「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」とは、どういう意味ですか？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"いいえ、できません。","question":"自分のhSD01-013〈SorAZ〉が1人いる時、hBP07-068〈AZKi〉がコラボしました。この場合、コラボエフェクト「共に歩んできた軌跡」の能力で、hSD01-013〈SorAZ〉を〈ときのそら〉、〈SorAZ〉の2人分として数えることはできますか？","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"はい、加えられます。","question":"hBP04-089〈ツートンカラーパソコン〉を使い、自分のステージに色が1色で異なる色のホロメンとして、〈ときのそら〉と〈フワワ・アビスガード〉を選びました。この場合、選んだホロメンと同色の1stホロメンとして、hSD01-013〈SorAZ〉とhBP03-050〈FUWAMOCO〉を手札に加えられますか？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"そのホロメンが持つ色が1色のみであり、2人以上いることを指します。例としてhBP01-021〈ときのそら〉は持っている色が1色ですが、hSD01-013〈SorAZ〉は持っている色が2色となります。","question":"hBP04-089〈ツートンカラーパソコン〉の「色が1色で異なる色のホロメン」とはどういう意味ですか？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"はい、可能です。","question":"hBP02-078〈かなた建設〉を使用して、hSD01-013〈SorAZ〉を手札に加えることができますか？","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"いいえ、hBP01-124〈開拓者〉はアーカイブされます。","question":"hBP01-124〈開拓者〉が付けられている自分のhSD01-013〈SorAZ〉を、hBP01-023〈ときのそら〉にBloomした場合、hBP01-124〈開拓者〉は付けたままになりますか？","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"はい、どちらの能力も発揮します。hSD01-013〈SorAZ〉は、エクストラにより〈ときのそら〉〈AZKi〉として扱うため、どちらのカード名のホロメンもステージにいるものとして扱います。","question":"hSD01-013〈SorAZ〉がセンターポジションにいる状態で、自分のhSD01-015〈博衣こより〉がコラボした場合、コラボエフェクトの能力はどちらの能力も発揮しますか？","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"はい、扱います。","question":"hSD01-013〈SorAZ〉のエクストラ「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」とは、ステージ以外にある場合でも〈ときのそら〉〈AZKi〉として扱いますか？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"はい、使用できます。アーツの使用の宣言後、テキストに書かれている効果を可能な限り解決してから、アーツダメージを与えます。","question":"hSD01-013〈SorAZ〉のアーツ「越えたい未来」は自分のデッキ、またはエールデッキが０枚の場合でも使用できますか？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"はい、送れます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-011〈AZKi〉のアーツ「SorAZ グラビティ」は、自分のホロメンに〈ときのそら〉がいなくてもhSD01-013〈SorAZ〉がいれば自分のエールデッキの上から１枚を、自分のホロメンに送れますか？","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"ko":[{"answer":"카드 이름으로서 〈ときのそら〉, 〈AZKi〉, 〈SorAZ〉를 모두 가진다는 의미입니다.","question":"hSD01-013〈SorAZ〉의 엑스트라 능력인 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」는 무슨 의미인가요?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"아니요, 할 수 없습니다.","question":"자신의 hSD01-013〈SorAZ〉가 1명 있을 때, hBP07-068〈AZKi〉가 콜라보했습니다. 이 경우, 콜라보 효과 「함께 걸어온 궤적」의 능력으로 hSD01-013〈SorAZ〉를 〈ときのそら〉, 〈SorAZ〉 두 사람으로 계산할 수 있나요?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"네, 추가할 수 있습니다.","question":"hBP04-089〈ツートンカラーパソコン〉을 사용하여, 자신의 스테이지에서 색이 각각 다른 홀로멘으로 〈ときのそら〉와 〈フワワ・アビスガード〉를 선택했습니다. 이 경우, 선택한 홀로멘과 같은 색의 1st 홀로멘으로서 hSD01-013〈SorAZ〉와 hBP03-050〈FUWAMOCO〉를 패에 추가할 수 있나요?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"그 홀로멘이 가진 색이 한 가지뿐이며, 2명 이상 있는 것을 말합니다. 예를 들어 hBP01-021〈ときのそら〉는 가진 색이 한 가지지만, hSD01-013〈SorAZ〉는 가진 색이 두 가지입니다.","question":"hBP04-089〈ツートンカラーパソコン〉의 「색이 한 가지이며 서로 다른 색의 홀로멘」이란 무슨 뜻인가요?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"네, 가능합니다.","question":"hBP02-078〈かなた建設〉을 사용해서, hSD01-013〈SorAZ〉를 패에 넣을 수 있나요?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250(2024.12.12)"},{"answer":"아니요, hBP01-124〈개척자〉는 아카이브됩니다.","question":"hBP01-124〈개척자〉가 붙어 있는 자신의 hSD01-013〈SorAZ〉를 hBP01-023〈ときのそら〉로 Bloom했을 경우, hBP01-124〈개척자〉는 그대로 유지되나요?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 개척자]"},"title":"Q116（2024.09.21）"},{"answer":"네, 가능합니다. 카드명에 해당 카드가 없더라도 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」와 같이 특정 카드명으로 취급되는 카드가 있다면 조건을 만족합니다.","question":"hSD01-021〈First Gravity〉의 「〈ときのそら〉와 〈AZKi〉를 원하는 수만큼 공개하고,」라는 텍스트가 있을 때, hSD01-013〈SorAZ〉를 공개하고 손패에 넣을 수 있나요?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"네, 두 능력 모두 발휘됩니다. hSD01-013〈SorAZ〉는 엑스트라에 의해 〈ときのそら〉〈AZKi〉로 취급되므로, 두 카드 이름의 홀로멘이 스테이지에 있는 것으로 간주합니다.","question":"hSD01-013〈SorAZ〉가 센터 포지션에 있을 때, 자신의 hSD01-015〈博衣こより〉가 콜라보한 경우, 콜라보 이펙트의 능력은 둘 다 발휘되나요?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"네, 취급합니다.","question":"hSD01-013〈SorAZ〉의 엑스트라 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」는 스테이지 이외의 영역에서도 〈ときのそら〉〈AZKi〉로 취급되나요?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"네, 사용할 수 있습니다. 아츠 사용을 선언한 후, 텍스트에 적힌 효과를 가능한 한 해결한 뒤 아츠 대미지를 줍니다.","question":"hSD01-013〈SorAZ〉의 아츠 「넘고 싶은 미래」는 내 덱이나 응원 덱이 0장일 때도 사용할 수 있나요?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"네, 보낼 수 있습니다. 카드명에 해당 카드가 없더라도, 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」처럼 특정 카드명으로 취급하는 카드가 존재하는 경우, 그 조건을 만족합니다.","question":"hSD01-011〈AZKi〉의 아츠 「SorAZ 그래비티」는, 내 홀로멘에 〈ときのそら〉가 없어도 hSD01-013〈SorAZ〉가 있으면 내 응원 덱 위에서 1장을 내 홀로멘에게 보낼 수 있나요?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"네, +50이 됩니다. 카드명에 해당 카드가 없더라도 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」와 같이 특정 카드명으로 취급되는 카드가 있다면 조건을 만족합니다.","question":"hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」는 자신의 홀로멘에 hSD01-013〈SorAZ〉가 있을 때에도 ''이 아츠 +50.''이 되나요?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"tc":[{"answer":"表示該卡同時擁有〈ときのそら〉、〈AZKi〉、〈SorAZ〉三個卡名。","question":"hSD01-013〈SorAZ〉的額外能力「此ホロ成員同時視為〈ときのそら〉與〈AZKi〉」是什麼意思？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"不，可以。","question":"當自己場上有1位hSD01-013〈SorAZ〉時，hBP07-068〈AZKi〉進行合作。此時能否因合作效果「共同走過的軌跡」的能力，將hSD01-013〈SorAZ〉視為〈ときのそら〉與〈SorAZ〉兩人分來計算？","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"是的，可以加入。","question":"使用hBP04-089〈ツートンカラーパソコン〉，在自己的舞台上，選擇不同顏色的Holomen〈ときのそら〉與〈フワワ・アビスガード〉。這種情況下，能否將hSD01-013〈SorAZ〉與hBP03-050〈FUWAMOCO〉作為與所選Holomen同色的1st Holomen加入手牌？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"是指該Holomen僅擁有1種顏色，且有2位或以上。例如hBP01-021〈ときのそら〉僅有1種顏色，而hSD01-013〈SorAZ〉則擁有2種顏色。","question":"hBP04-089〈ツートンカラーパソコン〉中「顏色各為單一且不同顏色的Holomen」是什麼意思？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"是的，可以。","question":"能否使用 hBP02-078〈かなた建設〉將 hSD01-013〈SorAZ〉加入手牌？","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"不會，hBP01-124〈開拓者〉會被送入檔案區域。","question":"若我場上的hSD01-013〈SorAZ〉裝備了hBP01-124〈開拓者〉，當我以〈ときのそら〉進行Bloom時，hBP01-124〈開拓者〉會保留在原位嗎？","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"可以，可以這麼做。即使卡名稱不符合，只要該卡具有如「此ホロ成員同時視為〈ときのそら〉與〈AZKi〉」之類的額外效果，也視為符合條件。","question":"hSD01-021〈First Gravity〉的效果「公開任意張〈ときのそら〉與〈AZKi〉，」中，是否可以公開hSD01-013〈SorAZ〉並將其加入手牌？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"會，兩個能力都會發動。由於hSD01-013〈SorAZ〉的額外能力使其同時視為〈ときのそら〉與〈AZKi〉，因此被視為舞台上同時存在這兩張卡名的Holomen。","question":"若hSD01-013〈SorAZ〉位於中央位置，並讓自己的hSD01-015〈博衣こより〉進行合作時，合作效果會同時發動兩張卡的能力嗎？","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"是的，仍會視為如此。","question":"hSD01-013〈SorAZ〉的額外效果「此ホロ成員同時視為〈ときのそら〉與〈AZKi〉」是否在不在舞台時仍視為〈ときのそら〉與〈AZKi〉？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"可以使用。宣告使用藝術後，會盡可能解決效果文字，再造成藝術傷害。","question":"hSD01-013〈SorAZ〉的藝術「想跨越的未來」在自己牌庫或應援牌庫為0張的情況下仍能使用嗎？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"可以。即使沒有該卡名稱，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」此類效果，便能滿足條件。","question":"hSD01-011〈AZKi〉的藝術「SorAZ Gravity」，若自己場上沒有〈ときのそら〉，但有hSD01-013〈SorAZ〉時，是否仍可將應援牌庫頂的1張牌送給自己的Holomen？","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"會，會增加+50。即使卡名不一致，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似效果，便能滿足條件。","question":"hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」，當自己場上有hSD01-013〈SorAZ〉時，也會使「此藝術+50」嗎？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"th":[{"answer":"หมายถึงถือว่าการ์ดนี้มีชื่อการ์ดเป็น〈ときのそら〉, 〈AZKi〉 และ〈SorAZ〉พร้อมกัน","question":"ความหมายของเอฟเฟกต์พิเศษ “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉และ〈AZKi〉ด้วย” ในการ์ด hSD01-013〈SorAZ〉 คืออะไร?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"ไม่ได้ค่ะ","question":"เมื่อคุณมี hSD01-013〈SorAZ〉 1 คน และ hBP07-068〈AZKi〉 ทำการคอลแลบ ในกรณีนี้ ในความสามารถของคอลแลบเอฟเฟกต์ “เส้นทางที่เราเดินมาด้วยกัน” สามารถนับ hSD01-013〈SorAZ〉 เป็นทั้ง〈ときのそら〉และ〈SorAZ〉สองคนได้ไหม?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"ได้, หยิบเข้ามือได้","question":"เมื่อใช้ hBP04-089〈ツートンカラーパソコン〉 และเลือก〈ときのそら〉กับ〈フワワ・アビスガード〉เป็น Holomen ที่บนสเตจมีสีเพียง 1 สีและสีต่างกัน ในกรณีนี้ สามารถหยิบ hSD01-013〈SorAZ〉และ hBP03-050〈FUWAMOCO〉 ซึ่งเป็น 1st Holomen ที่มีสีเดียวกับ Holomen ที่เลือกเข้ามือได้หรือไม่?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"หมายถึงโฮโลเมมนั้นมีเพียงสีเดียว และมีมากกว่าหนึ่งคน ตัวอย่างเช่น〈ときのそら〉 hBP01-021 มีสีเดียว แต่〈SorAZ〉 hSD01-013 มีสองสี","question":"คำว่า “โฮโลเมมที่มีสีเดียวแต่เป็นคนละสี” ใน〈ツートンカラーパソコン〉หมายถึงอะไร?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"ได้ สามารถทำได้","question":"สามารถใช้〈かなた建設〉 hBP02-078 เพื่อนำ〈SorAZ〉 hSD01-013 เข้ามือได้หรือไม่?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"不會，hBP01-124〈開拓者〉會被置入檔案區域（アーカイブ）。","question":"如果把附有 hBP01-124〈開拓者〉的自己 hSD01-013〈SorAZ〉對 hBP01-023〈ときのそら〉進行 Bloom，hBP01-124〈開拓者〉會繼續附著嗎？","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"ได้ครับ/ค่ะ สามารถทำได้ แม้ชื่อการ์ดนั้นจะไม่ตรงกับชื่อที่ระบุ หากการ์ดเอ็กซ์ตรามีข้อความที่ทำให้การ์ดนั้น\"ถูกนับว่าเป็น〈ときのそら〉หรือ〈AZKi〉\" ก็ถือว่าเป็นไปตามเงื่อนไข","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"ได้ ทำงานทั้งสองฝั่ง เพราะ hSD01-013〈SorAZ〉 ถือว่าเป็น〈ときのそら〉และ〈AZKi〉 ด้วยจากเอฟเฟกต์พิเศษ จึงนับว่าโฮโลเมมทั้งสองชื่อนั้นอยู่บนสเตจ","question":"ถ้า hSD01-013〈SorAZ〉 อยู่ในตำแหน่งเซ็นเตอร์ แล้ว hSD01-015〈博衣こより〉 ของตัวเองทำคอลลาบ เอฟเฟกต์คอลลาบจะทำงานทั้งสองฝั่งไหม?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"ได้ ใช้ได้ทุกโซน","question":"เอฟเฟกต์พิเศษของ hSD01-013〈SorAZ〉 ที่ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” จะยังคงใช้ได้แม้อยู่ในโซนอื่นนอกจากสเตจไหม?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"ได้ สามารถใช้ได้ หลังจากประกาศใช้แอทส์ ให้แก้เอฟเฟกต์ในข้อความเท่าที่ทำได้ แล้วค่อยสร้างความเสียหายจากแอทส์","question":"สามารถใช้แอทส์ “越えたい未来” ของ〈SorAZ〉 hSD01-013 ได้หรือไม่ หากเด็คหรือกองเชียร์มี 0 ใบ?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"ได้ สามารถส่งได้ ถ้ามีการ์ดที่ระบุว่าในโซนเอ็กซ์ตราจะจัดการการ์ดนั้นเป็นการ์ดชื่อเฉพาะ เช่น “การ์ดนี้จะถูกนับเป็น〈ときのそら〉〈AZKi〉ด้วย” แม้ว่าจะไม่มีชื่อการ์ดตรงตามเงื่อนไขบนการ์ดก็ตาม มันก็จะถือว่าตรงตามเงื่อนไขนั้น","question":"อาร์ทของ hSD01-011〈AZKi〉ชื่อ「SorAZ แรงโน้มถ่วง」 ถ้าบนสเตจของตนไม่มี〈ときのそら〉 แต่มี hSD01-013〈SorAZ〉 อยู่ สามารถส่งไพ่จากด้านบนของเด็คเยลของตน 1 ใบไปยังโฮโลเมนของตนได้ไหม？","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"ได้ครับ/ค่ะ จะได้รับ +50 แม้จะไม่มีการกล่าวถึงชื่อการ์ดที่ตรงกันในชื่อการ์ด แต่ถ้ามีความสามารถพิเศษในเอ็กซ์ตราที่ระบุว่า \"โฮโลเมนนี้ถือเป็น〈ときのそら〉และ〈AZKi〉ด้วย\" แบบนี้ ก็ถือว่าตรงตามเงื่อนไข","question":"อาร์ท \"SorAZ シンパシー\" ของ hSD01-006〈ときのそら〉 จะได้รับ \"+50\" ถ้าในฝั่งของตัวเองมี hSD01-013〈SorAZ〉 อยู่หรือไม่?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}]}', 'b8f47c93d131c939bc2f1b21dd831ad28cb282e1a977b9d95678a522474d00f1', '69fb2d5467f461e0338a9a909d1376a03c9ae80c3a63f04a8283ac6f4c148706', '1970-01-01T00:00:00Z');
