INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('18', 'hSD01-018', 'supportItem', 'C', NULL, 'hSD01/hSD01-018_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-018_C.png', NULL, NULL, NULL, NULL, 'JinArt こばやかわやまと', 'サブパソコン', '{"card_sets":["エクストラブースター サマー・ホログラム","スタートデッキ「ときのそら＆AZKi」","スタートデッキ 赤 百鬼あやめ","スタートデッキ 黄 不知火フレア","【使用可能カード】hGS 2026 大阪 セレクションロード"],"translations":{"en":{"ability_text":"Look at the top 5 cards of your deck. Reveal 1 LIMITED Support card from among them and add it to your hand. Then put the remaining cards on the bottom of your deck in any order.","name":"Sub PC"},"es":{"ability_text":"Mira las 5 cartas de la parte superior de tu mazo. De entre ellas, muestra 1 carta de Support con LIMITED y añádela a tu mano. Luego devuelve las cartas restantes al fondo del mazo en el orden que quieras.","name":"Sub PC"},"id":{"ability_text":"Lihat 5 kartu teratas dari dekmu. Dari antaranya, ungkapkan 1 kartu Support dengan LIMITED, lalu tambahkan ke tanganmu. Kemudian kembalikan sisa kartunya ke bagian bawah dekmu dalam urutan sesukamu.","name":"Sub PC"},"ja":{"ability_text":"自分のデッキの上から5枚を見る。その中から、LIMITEDのサポートカード1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"サブパソコン"},"ko":{"ability_text":"자신의 덱 위에서부터 5장을 본다. 그중에서, LIMITED 서포트 카드 1장을 공개하고, 손패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.","name":"서브 PC"},"tc":{"ability_text":"查看自己牌庫頂的5張牌。從中公開1張LIMITED的支援卡，加入手牌。然後將剩餘的卡以任意順序放回牌庫底。","name":"副電腦"},"th":{"ability_text":"ดูการ์ด 5 ใบบนสุดของเด็คของคุณ จากนั้นเปิดเผยซัพพอร์ตการ์ดที่มี LIMITED 1 ใบจากในนั้น และนำเข้ามือ แล้วนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับใดก็ได้","name":"ซับพีซี"}}}', '{}', '02e1e426cb4df37a3523b22b2de7a6c7cc7f85625c398f9dff4157e67cfc3719', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
