INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (19, 'hSD01-019', 'hSD01-019 JinArt KABAKURA スゴイパソコン このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('20', 'hSD01-020', 'supportEvent', 'C', NULL, 'hSD01/hSD01-020_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-020_C.png', NULL, NULL, NULL, NULL, 'JinArt KABAKURA', 'ホロリスの輪', '{"card_sets":["ブースターパック「ブルーミングレディアンス」","スタートデッキ「ときのそら＆AZKi」"],"translations":{"en":{"ability_text":"Roll a die once: If the result is 3 or higher, send 1 Cheer from your Archive to your holomem.","name":"Hololist Circle"},"es":{"ability_text":"Lanza 1 dado: si el resultado es 3 o más, envía 1 Cheer de tu Archive a uno de tus holomen.","name":"Hololist Circle"},"id":{"ability_text":"Lempar 1 dadu: jika hasilnya 3 atau lebih, kirim 1 Cheer dari Archive-mu ke holomen milikmu.","name":"Lingkaran Hololist"},"ja":{"ability_text":"サイコロを1回振る:3以上の時、自分のアーカイブのエール1枚を自分のホロメンに送る。","name":"ホロリスの輪"},"ko":{"ability_text":"주사위를 1번 굴린다: 3 이상이면, 자신의 Archive의 에일 1장을 자신의 홀로멤에게 보낸다.","name":"홀로리스의 고리"},"tc":{"ability_text":"擲 1 次骰子：若為 3 以上，將自己 Archive 的 1 張 Cheer 送到自己的 holomen。","name":"Holo友的圈圈"},"th":{"ability_text":"ทอยลูกเต๋า 1 ครั้ง: ถ้าได้ 3 ขึ้นไป ส่ง Cheer 1 ใบจาก Archive ของคุณไปยังโฮโลเมมของคุณ","name":"วงกลมโฮโลริส"}}}', '{"en":[{"answer":"No, you can’t. If you don’t have any Cheers in your Archive, you also cannot roll the die.","question":"Can I use hSD01-020〈ホロリスの輪〉 when I don’t have any Cheers in my Archive?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554 (2026.01.16)"},{"answer":"Yes, the Arts damage is increased. Regardless of the die result, since the effect of the Support Card is activated, it is considered to have been used, so the Arts damage increases.","question":"When using hSD01-020〈ホロリスの輪〉 and the die roll result is 2 or less, if I use the Arts ‘Oh,Hi’ of hBP01-015〈七詩ムメイ〉, is the Arts damage increased?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50 (2024.09.21)"}],"es":[{"answer":"No, no se puede. Si no tienes ninguna carta de Aplauso en tu Archivo, tampoco puedes simplemente lanzar el dado.","question":"¿Se puede usar hSD01-020〈ホロリスの輪〉 cuando no tienes ninguna carta de Aplauso en tu Archivo?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"Sí, el daño del arte se incrementa. Sin importar el resultado del dado, la habilidad de la carta de apoyo se considera activada, por lo que se considera como usada y el daño del arte aumenta.","question":"Si uso hSD01-020〈ホロリスの輪〉 y el resultado del dado es 2 o menos, cuando uso el arte «Oh,Hi» de hBP01-015〈七詩ムメイ〉, ¿el daño del arte se incrementa?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"id":[{"answer":"Tidak bisa. Jika di Arsipmu tidak ada Yell, kamu juga tidak dapat hanya melempar dadu saja.","question":"Apakah saya bisa menggunakan hSD01-020〈Holoris no Wa〉 ketika di Arsip saya tidak ada Yell?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： Holoris no Wa]"},"title":"Q554（2026.01.16）"},{"answer":"Ya, damage arts akan bertambah. Terlepas dari hasil dadu, kemampuan kartu Support tetap aktif, sehingga dianggap telah digunakan dan menambah damage arts.","question":"Jika menggunakan hSD01-020〈ホロリスの輪〉 dan hasil dadu 2 atau kurang, lalu menggunakan arts \"Oh,Hi\" dari hBP01-015〈七詩ムメイ〉, apakah damage arts akan bertambah?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"ja":[{"answer":"いいえ、できません。自分のアーカイブにエールがない場合、サイコロのみを振ることもできません。","question":"自分のアーカイブにエールがない時に、hSD01-020〈ホロリスの輪〉を使用することはできますか？","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"はい、アーツダメージはプラスされます。サイコロの結果は問わず、サポートカードの能力は発揮されているので、使用したとみなされアーツダメージがプラスされます。","question":"hSD01-020〈ホロリスの輪〉を使用し、サイコロの目が2以下の時に、hBP01-015〈七詩ムメイ〉のアーツ「Oh,Hi」を使用した場合、アーツダメージはプラスされますか？","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"ko":[{"answer":"아니요, 사용할 수 없습니다. 자신의 아카이브에 에ール이 없을 경우, 주사위만 굴리는 것도 불가능합니다.","question":"자신의 아카이브에 에ール이 없을 때, hSD01-020〈ホロリスの輪〉을(를) 사용할 수 있나요?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"네, 아츠 데미지가 추가됩니다. 주사위 결과와 관계없이 서포트 카드의 능력이 발휘되고 있으므로, 사용된 것으로 간주되어 아츠 데미지가 추가됩니다.","question":"hSD01-020〈ホロリスの輪〉을(를) 사용해서 주사위 눈이 2 이하일 때, hBP01-015〈七詩ムメイ〉의 아츠 「Oh,Hi」를 사용하면, 아츠 데미지가 추가되나요?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"tc":[{"answer":"不可以。若自己的檔案區域中沒有應援卡，則無法僅擲骰子。","question":"當自己的檔案區域中沒有應援卡時，可以使用hSD01-020〈Holoris之環〉嗎？","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： Holoris之環]"},"title":"Q554（2026.01.16）"},{"answer":"會，藝術傷害會增加。無論骰子結果如何，因為支援卡的能力已經發動，所以視為已使用，藝術傷害會增加。","question":"使用hSD01-020〈Holoris之環〉時，若骰子點數為2以下，再使用hBP01-015〈七詩ムメイ〉的アーツ「Oh,Hi」，藝術傷害會增加嗎？","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： Holoris之環]"},"title":"Q50（2024.09.21）"}],"th":[{"answer":"ไม่สามารถทำได้ ถ้าในพื้นที่จดจำของตัวเองไม่มีเอียร์ จะไม่สามารถทอยลูกเต๋าเพียงอย่างเดียวได้เช่นกัน","question":"สามารถใช้ hSD01-020〈ホロリスの輪〉 ได้หรือไม่ หากในพื้นที่จดจำของตัวเองไม่มีเอียร์?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"ใช่ จะถูกบวก ความสามารถของการ์ดซัพพอร์ตถือว่าแสดงผลไม่ว่าแต้มลูกเต๋าจะเป็นเท่าไรก็ตาม ดังนั้นถือว่าได้ใช้และความเสียหายอーツจะถูกบวก","question":"ถ้าใช้ hSD01-020〈ホロリスの輪〉 และผลลูกเต๋าเป็น 2 หรือน้อยกว่า แล้วใช้อーツ “Oh,Hi” ของ hBP01-015〈七詩ムメイ〉 ความเสียหายอーツจะถูกบวกไหม?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}]}', '9113226872bbd3b1440a6e68894d0727d977d51aa87c902cdd171dd185854954', 'bac63d20bbcd35739a24c80697dec13ddb0d9815d6de565dce38adbfddf984b6', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「ブルーミングレディアンス」', '20');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '20');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (20, 'hSD01-020', 'hSD01-020 JinArt KABAKURA ホロリスの輪 サイコロを1回振る:3以上の時、自分のアーカイブのエール1枚を自分のホロメンに送る。 Hololist Circle Roll a die once: If the result is 3 or higher, send 1 Cheer from your Archive to your holomem. Holo友的圈圈 擲 1 次骰子：若為 3 以上，將自己 Archive 的 1 張 Cheer 送到自己的 holomen。 Lingkaran Hololist Lempar 1 dadu: jika hasilnya 3 atau lebih, kirim 1 Cheer dari Archive-mu ke holomen milikmu. 홀로리스의 고리 주사위를 1번 굴린다: 3 이상이면, 자신의 Archive의 에일 1장을 자신의 홀로멤에게 보낸다. วงกลมโฮโลริส ทอยลูกเต๋า 1 ครั้ง: ถ้าได้ 3 ขึ้นไป ส่ง Cheer 1 ใบจาก Archive ของคุณไปยังโฮโลเมมของคุณ Hololist Circle Lanza 1 dado: si el resultado es 3 o más, envía 1 Cheer de tu Archive a uno de tus holomen.', 'Q554（2026.01.16） 自分のアーカイブにエールがない時に、hSD01-020〈ホロリスの輪〉を使用することはできますか？ いいえ、できません。自分のアーカイブにエールがない場合、サイコロのみを振ることもできません。 Q50（2024.09.21） hSD01-020〈ホロリスの輪〉を使用し、サイコロの目が2以下の時に、hBP01-015〈七詩ムメイ〉のアーツ「Oh,Hi」を使用した場合、アーツダメージはプラスされますか？ はい、アーツダメージはプラスされます。サイコロの結果は問わず、サポートカードの能力は発揮されているので、使用したとみなされアーツダメージがプラスされます。 Q554 (2026.01.16) Can I use hSD01-020〈ホロリスの輪〉 when I don’t have any Cheers in my Archive? No, you can’t. If you don’t have any Cheers in your Archive, you also cannot roll the die. Q50 (2024.09.21) When using hSD01-020〈ホロリスの輪〉 and the die roll result is 2 or less, if I use the Arts ‘Oh,Hi’ of hBP01-015〈七詩ムメイ〉, is the Arts damage increased? Yes, the Arts damage is increased. Regardless of the die result, since the effect of the Support Card is activated, it is considered to have been used, so the Arts damage increases. Q554（2026.01.16） 當自己的檔案區域中沒有應援卡時，可以使用hSD01-020〈Holoris之環〉嗎？ 不可以。若自己的檔案區域中沒有應援卡，則無法僅擲骰子。 Q50（2024.09.21） 使用hSD01-020〈Holoris之環〉時，若骰子點數為2以下，再使用hBP01-015〈七詩ムメイ〉的アーツ「Oh,Hi」，藝術傷害會增加嗎？ 會，藝術傷害會增加。無論骰子結果如何，因為支援卡的能力已經發動，所以視為已使用，藝術傷害會增加。 Q554（2026.01.16） Apakah saya bisa menggunakan hSD01-020〈Holoris no Wa〉 ketika di Arsip saya tidak ada Yell? Tidak bisa. Jika di Arsipmu tidak ada Yell, kamu juga tidak dapat hanya melempar dadu saja. Q50（2024.09.21） Jika menggunakan hSD01-020〈ホロリスの輪〉 dan hasil dadu 2 atau kurang, lalu menggunakan arts "Oh,Hi" dari hBP01-015〈七詩ムメイ〉, apakah damage arts akan bertambah? Ya, damage arts akan bertambah. Terlepas dari hasil dadu, kemampuan kartu Support tetap aktif, sehingga dianggap telah digunakan dan menambah damage arts. Q554（2026.01.16） 자신의 아카이브에 에ール이 없을 때, hSD01-020〈ホロリスの輪〉을(를) 사용할 수 있나요? 아니요, 사용할 수 없습니다. 자신의 아카이브에 에ール이 없을 경우, 주사위만 굴리는 것도 불가능합니다. Q50（2024.09.21） hSD01-020〈ホロリスの輪〉을(를) 사용해서 주사위 눈이 2 이하일 때, hBP01-015〈七詩ムメイ〉의 아츠 「Oh,Hi」를 사용하면, 아츠 데미지가 추가되나요? 네, 아츠 데미지가 추가됩니다. 주사위 결과와 관계없이 서포트 카드의 능력이 발휘되고 있으므로, 사용된 것으로 간주되어 아츠 데미지가 추가됩니다. Q554（2026.01.16） สามารถใช้ hSD01-020〈ホロリスの輪〉 ได้หรือไม่ หากในพื้นที่จดจำของตัวเองไม่มีเอียร์? ไม่สามารถทำได้ ถ้าในพื้นที่จดจำของตัวเองไม่มีเอียร์ จะไม่สามารถทอยลูกเต๋าเพียงอย่างเดียวได้เช่นกัน Q50（2024.09.21） ถ้าใช้ hSD01-020〈ホロリスの輪〉 และผลลูกเต๋าเป็น 2 หรือน้อยกว่า แล้วใช้อーツ “Oh,Hi” ของ hBP01-015〈七詩ムメイ〉 ความเสียหายอーツจะถูกบวกไหม? ใช่ จะถูกบวก ความสามารถของการ์ดซัพพอร์ตถือว่าแสดงผลไม่ว่าแต้มลูกเต๋าจะเป็นเท่าไรก็ตาม ดังนั้นถือว่าได้ใช้และความเสียหายอーツจะถูกบวก Q554（2026.01.16） ¿Se puede usar hSD01-020〈ホロリスの輪〉 cuando no tienes ninguna carta de Aplauso en tu Archivo? No, no se puede. Si no tienes ninguna carta de Aplauso en tu Archivo, tampoco puedes simplemente lanzar el dado. Q50（2024.09.21） Si uso hSD01-020〈ホロリスの輪〉 y el resultado del dado es 2 o menos, cuando uso el arte «Oh,Hi» de hBP01-015〈七詩ムメイ〉, ¿el daño del arte se incrementa? Sí, el daño del arte se incrementa. Sin importar el resultado del dado, la habilidad de la carta de apoyo se considera activada, por lo que se considera como usada y el daño del arte aumenta.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('21', 'hSD01-021', 'supportEventLimited', 'C', NULL, 'hSD01/hSD01-021_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-021_C.png', NULL, NULL, NULL, NULL, '© 2023 Victor Entertainment. © 2016 COVER Corp.', 'First Gravity', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"translations":{"en":{"ability_text":"You may play this card only if you have 6 or fewer cards in your hand, not counting this card.\n\nLook at the top 4 cards of your deck. From among them, reveal any number of 〈Tokino Sora〉 and 〈AZKi〉 holomem, and put the revealed holomem into your hand. Then return the remaining cards to the bottom of your deck in any order.\n\nLIMITED: You may play only 1 per turn.","name":"First Gravity"},"es":{"ability_text":"Esta carta solo se puede usar si tienes 6 cartas o menos en la mano, sin contar esta carta.\n\nMira las 4 cartas de la parte superior de tu mazo. De entre ellas, revela cualquier cantidad de holomen con 〈Tokino Sora〉 y 〈AZKi〉, añade a tu mano los holomen revelados y devuelve las cartas restantes al fondo del mazo en el orden que prefieras.\n\nLIMITED: Solo puedes usar 1 carta por turno.","name":"First Gravity"},"id":{"ability_text":"Kartu ini hanya bisa digunakan jika kartu di hand Anda, selain kartu ini, berjumlah 6 atau kurang.\n\nLihat 4 kartu teratas dari deck Anda. Dari antaranya, ungkapkan sejumlah kartu 〈Tokino Sora〉 dan 〈AZKi〉 sesuka Anda, lalu tambahkan Holomen yang diungkapkan ke hand Anda. Lalu, kembalikan sisa kartunya ke bawah deck dalam urutan sesuka Anda.\n\nLIMITED: Hanya 1 kartu yang bisa digunakan per turn.","name":"First Gravity"},"ja":{"ability_text":"このカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。\n\r\n自分のデッキの上から4枚を見る。その中から、〈ときのそら〉と〈AZKi〉を好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\n\r\nLIMITED:ターンに1枚しか使えない。","name":"First Gravity"},"ko":{"ability_text":"이 카드는, 이 카드를 제외한 자신의 패가 6장 이하여야만 사용할 수 있다.\n\n자신의 덱 위에서부터 4장을 본다. 그 중에서 〈토키노 소라〉와 〈AZKi〉를 원하는 수만큼 공개하고, 공개한 홀로멘을 패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.\n\nLIMITED: 턴에 1장만 사용할 수 있다.","name":"First Gravity"},"tc":{"ability_text":"這張卡只有在自己的手牌不包含這張卡為6張以下時才能使用。\n\n查看自己牌庫頂的4張牌。從中公開任意張帶有〈時乃空〉與〈AZKi〉的holomen，將公開的holomen加入手牌。然後將剩下的牌以任意順序放回牌庫底。\n\nLIMITED：每回合只能使用1張。","name":"First Gravity"},"th":{"ability_text":"การ์ดใบนี้จะใช้ได้ก็ต่อเมื่อการ์ดบนมือของคุณโดยไม่นับการ์ดใบนี้มี 6 ใบหรือน้อยกว่า\n\nดูการ์ด 4 ใบบนสุดของเด็คคุณ จากนั้นเปิดเผยโฮโลเมนที่มี 〈โตกิโนะ โซระ〉และ〈AZKi〉จากในนั้นได้ตามจำนวนที่ต้องการ แล้วนำโฮโลเมนที่เปิดเผยขึ้นมือ หลังจากนั้นนำการ์ดที่เหลือกลับไปไว้ก้นเด็คในลำดับใดก็ได้\n\nLIMITED: ใช้ได้เพียง 1 ใบต่อเทิร์น","name":"First Gravity"}}}', '{"en":[{"answer":"Yes, you can. Even if the card name doesn’t directly match, as long as there is a card with an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉”, it satisfies that condition.","question":"In hSD01-021〈First Gravity〉’s text, it says “Reveal any number of 〈ときのそら〉 and 〈AZKi〉 cards.” Can I reveal hSD01-013〈SorAZ〉 and add it to my hand?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17 (2024.09.21)"},{"answer":"Yes, it is included.","question":"Regarding hBP01-021〈First Gravity〉''s ''This card can only be used if you have 6 or less cards in hand excluding this card.'' does this include when you have exactly 6 cards?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021: First Gravity]"},"title":"Q16（September 21, 2024）"}],"es":[{"answer":"Sí, puedes. Aunque no exista una carta con ese nombre exacto, si en el Extra hay una carta que indique algo como «esta Holomen también cuenta como 〈ときのそら〉 y 〈AZKi〉», entonces cumple con las condiciones.","question":"En el texto de hSD01-021〈First Gravity〉 dice «puedes revelar cualquier número de 〈ときのそら〉 y 〈AZKi〉». ¿Puedo revelar y añadir a la mano una hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Sí, lo incluye.","question":"En el texto de hSD01-021〈First Gravity〉 dice «Solo puedes usar esta carta si, sin contar esta carta, tienes 6 o menos cartas en tu mano». ¿Incluye el caso cuando tienes exactamente 6?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"id":[{"answer":"Ya, bisa. Walaupun tidak ada kartu dengan nama yang sama, jika ada kartu dengan efek ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Pada hSD01-021〈First Gravity〉tertulis “perlihatkan sebanyak yang kamu mau kartu〈ときのそら〉dan〈AZKi〉”. Apakah aku bisa memperlihatkan hSD01-013〈SorAZ〉dan menambahkannya ke tangan?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Ya, termasuk.","question":"Di hSD01-021〈First Gravity〉 tertulis “Kartu ini hanya bisa digunakan jika jumlah kartu di tangan Anda, tidak termasuk kartu ini, adalah 6 kartu atau kurang.” apakah itu termasuk saat jumlahnya 6?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"ja":[{"answer":"はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"はい、含みます。","question":"hSD01-021〈First Gravity〉の「このカードは、自分の手札がこのカードを含まずに６枚以下でなければ使えない。」とは6枚のときも含みますか？","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"ko":[{"answer":"네, 가능합니다. 카드명에 해당 카드가 없더라도 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」와 같이 특정 카드명으로 취급되는 카드가 있다면 조건을 만족합니다.","question":"hSD01-021〈First Gravity〉의 「〈ときのそら〉와 〈AZKi〉를 원하는 수만큼 공개하고,」라는 텍스트가 있을 때, hSD01-013〈SorAZ〉를 공개하고 손패에 넣을 수 있나요?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"네, 포함됩니다.","question":"hSD01-021〈First Gravity〉의 「이 카드는, 자신의 패가 이 카드를 제외하고 6장 이하일 때만 사용할 수 있다.」라는 조건은 6장일 때도 포함되나요?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"tc":[{"answer":"可以，可以這麼做。即使卡名稱不符合，只要該卡具有如「此ホロ成員同時視為〈ときのそら〉與〈AZKi〉」之類的額外效果，也視為符合條件。","question":"hSD01-021〈First Gravity〉的效果「公開任意張〈ときのそら〉與〈AZKi〉，」中，是否可以公開hSD01-013〈SorAZ〉並將其加入手牌？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"是的，包含。","question":"hSD01-021〈First Gravity〉的「這張卡必須在自己的手牌不包含這張卡的情況下為6張以下才能使用。」是否包含正好6張的情況？","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"th":[{"answer":"ได้ครับ/ค่ะ สามารถทำได้ แม้ชื่อการ์ดนั้นจะไม่ตรงกับชื่อที่ระบุ หากการ์ดเอ็กซ์ตรามีข้อความที่ทำให้การ์ดนั้น\"ถูกนับว่าเป็น〈ときのそら〉หรือ〈AZKi〉\" ก็ถือว่าเป็นไปตามเงื่อนไข","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"ใช่ รวมถึงตอนที่มี 6 ใบด้วย","question":"hSD01-021〈First Gravity〉の「このカードは、自分の手札がこのカードを含まずに６枚以下でなければ使えない。」とは6枚のときも含みますか？","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}]}', 'aed9638e6c35c3b4f3344b28723bf61b35eb7559c194b20e571b48ab3ab915a7', 'c46af3a37e86b4b4d85e1e261dda097b77aa6ae8dc244deece8d20f6fd6d25b4', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '21');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (21, 'hSD01-021', 'hSD01-021 © 2023 Victor Entertainment. © 2016 COVER Corp. First Gravity このカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('23', 'hBP01-001', 'oshiCharacter', 'OUR', NULL, 'hBP01/hBP01-001_OUR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-001_OUR.png', NULL, 5, NULL, NULL, 'Hiroko', '天音かなた', '{"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Amane Kanata","oshi_skill":{"effect":"[Once per turn] Set your opponent''s Center holomem''s remaining HP to 50.","name":"Squeeze Squeeze","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] During this turn, 1 of your holomem gets +50 Arts. If that holomem''s color is white, it gets an additional +50 Arts.","name":"I''ll crush you in my grip!","timing":"Once per game"}},"es":{"name":"Amane Kanata","oshi_skill":{"effect":"[Una vez por turno] Los PS restantes del holomen central de tu oponente pasan a ser 50.","name":"Apretujón, apretujón","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Durante este turno, las artes de 1 de tus holomen obtienen +50. Si el color de ese holomen es blanco, además, esas artes obtienen +50.","name":"¡Te aplastaré con mi mano!","timing":"Una vez por partida"}},"id":{"name":"Amane Kanata","oshi_skill":{"effect":"[Sekali per giliran] Jadikan sisa HP Center Holomen lawan menjadi 50.","name":"Peluk erat erat","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Selama giliran ini, Arts 1 holomen milikmu +50. Jika warna holomen itu putih, tambahan Arts itu +50 lagi.","name":"Akan kuhancurkan dalam genggamanku","timing":"Sekali per permainan"}},"ja":{"name":"天音かなた","oshi_skill":{"effect":"[ターンに1回]相手のセンターホロメンの残りHPを50にする。","name":"ぎゅっぎゅっ","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]このターンの間、自分のホロメン1人のアーツ+50。そのホロメンの色が白の時、さらに、そのアーツ+50。","name":"握りつぶしちゃうぞ","timing":"ゲームに1回"}},"ko":{"name":"아마네 카나타","oshi_skill":{"effect":"[턴에 1번]상대의 센터 홀로멤의 남은 HP를 50으로 한다.","name":"꼬옥꼬옥","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]이번 턴 동안 자신의 홀로멘 1명의 아츠+50. 그 홀로멘의 색이 흰색일 때 추가로 그 아츠+50.","name":"꽉 쥐어뭉개버릴 거야","timing":"게임에 1번"}},"tc":{"name":"天音彼方","oshi_skill":{"effect":"[每回合1次]將對手Center Holomen的剩餘HP變成50。","name":"緊緊抱抱","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]在這個回合期間，自己的1名holomen的藝術+50。當該holomen的顏色為白色時，則再使其藝術+50。","name":"我要把你捏碎喔","timing":"每場對戰1次"}},"th":{"name":"อามาเนะ คานาตะ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ทำให้ HP ที่เหลือของเซ็นเตอร์โฮโลเม็มเบอร์ของฝ่ายตรงข้ามเป็น 50","name":"กอดแน่นๆ","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ในเทิร์นนี้ อาร์ตของโฮโลเมนของคุณ 1 คน +50 ถ้าโฮโลเมนนั้นมีสีขาว อาร์ตนั้นจะ +50 เพิ่มเติม","name":"จะบีบให้แหลกเลยนะ","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{"en":[{"answer":"No, you can’t.","question":"Can you set the remaining HP of a Buzz Holomen equipped with hBP06-097〈カワイイスタジャン〉 to 50 using hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536 (2025.12.12)"},{"answer":"No, since the HP value does not change, it cannot become “50.”","question":"Can the gift “冷静沈着” of hBP04-024〈儒烏風亭らでん〉 cause the remaining HP to become “50” due to the oshi skill “ぎゅっぎゅっ” of hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382 (2025.06.11)"},{"answer":"Yes, you can.","question":"hBP01-001〈Amane Kanata〉 uses Oshi skill ''Squish Squish'' on 〈Tokino Sora〉 with hBP01-118〈Ankimo〉 attached.In this situation, can the HP of 〈Tokino Sora〉 with hBP01-118〈Ankimo〉 attached be set to 50?","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001: Amane Kanata]\n[hBP01-118: Ankimo]"},"title":"Q362（March 11, 2025）"},{"answer":"No, since HP does not change, it cannot become “50.”","question":"Can the Gift “Boxing Style” of hBP03-065〈戌神ころね〉 cause the remaining HP to become “50” due to the Oshi Skill “Gyuggyu” of hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327 (2025.03.11)"},{"answer":"No, it does not. The ability of hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu” does not deal damage, so hBP01-116〈うぱお〉’s ability does not trigger.","question":"When you use hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu” on your opponent’s center Holomen equipped with hBP01-116〈うぱお〉, does your own center Holomen take special damage from the effect of hBP01-116〈うぱお〉?","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26 (2024.09.21)"},{"answer":"No, you cannot. Since it does not deal damage, you cannot use hYS01-001〈七詩ムメイ〉’s SP oshi skill “Quick Guard” against hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”.","question":"Can you use hYS01-001〈七詩ムメイ〉’s SP oshi skill “Quick Guard” in response to hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25 (2024.09.21)"},{"answer":"No, you cannot. Since it does not deal damage, you cannot use hBP01-121〈Kotori〉’s ability against hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”.","question":"Can you use hBP01-121〈Kotori〉’s ability in response to hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”?","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24 (2024.09.21)"},{"answer":"No, you cannot. Since “ぎゅっぎゅっ” is not a damage-dealing ability, the ability of hBP01-117〈フレンド〉 cannot be used against hBP01-001〈天音かなた〉’s Oshi Skill “ぎゅっぎゅっ”.","question":"Can you use the ability of hBP01-117〈フレンド〉 against hBP01-001〈天音かなた〉’s Oshi Skill “ぎゅっぎゅっ”?","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23 (2024.09.21)"},{"answer":"No, you cannot. Since “ぎゅっぎゅっ” is not a damage-dealing ability, the Gift “V.7” of hBP01-027〈ベスティア・ゼータ〉 cannot be used against it.","question":"Can you use the Gift “V.7” of hBP01-027〈ベスティア・ゼータ〉 against the Oshi Skill “ぎゅっぎゅっ” of hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22 (2024.09.21)"},{"answer":"No, you cannot. Since hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu” does not deal damage, you cannot use hBP01-002〈七詩ムメイ〉’s oshi skill “Guardian of Civilization” in response.","question":"During your opponent’s turn, if one of your Holomen with #Promise would have its HP set to 50 by hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”, can hBP01-002〈七詩ムメイ〉’s oshi skill “Guardian of Civilization” reduce that damage by 50?","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21 (2024.09.21)"},{"answer":"No, it does not. The oshi skill “Gyuggyu” of hBP01-001〈天音かなた〉 sets the remaining HP directly and does not count as HP recovery.","question":"You used hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu” on an opponent’s Holomen that had 40 remaining HP and was equipped with 〈石の斧〉. When that Holomen’s HP becomes 50, does 〈石の斧〉’s ability “When this Holomen recovers HP” trigger?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20 (2024.09.21)"},{"answer":"The remaining HP of that opponent’s Holomen becomes 50.","question":"When you use hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu” on an opponent’s Holomen with 40 or less remaining HP, what happens to their HP?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19 (2024.09.21)"},{"answer":"No, you cannot. Since hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu” does not deal damage, you cannot reduce or avoid damage from it.","question":"When your center Holomen’s HP is reduced to 50 by hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”, can you use hBP01-027〈ベスティア・ゼータ〉’s gift “V.7” to avoid taking damage?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18 (2024.09.21)"}],"es":[{"answer":"No, no se puede.","question":"¿Se puede hacer que los HP restantes de un Holomen Buzz con hBP06-097〈カワイイスタジャン〉 sean 50 usando la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"No, no se puede, ya que los HP no se modifican, por lo tanto no pueden ser 50.","question":"¿La Gift «冷静沈着» de hBP04-024〈儒烏風亭らでん〉 puede hacer que los HP restantes sean 50 al usar la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"Sí, se puede.","question":"Se usó la habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉 sobre 〈ときのそら〉 que tiene anexado hBP01-118〈あん肝〉. En este caso, ¿se puede establecer el HP restante de 〈ときのそら〉 con hBP01-118〈あん肝〉 en ''50''?","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362（2025.03.11）"},{"answer":"No, no se puede, ya que los HP no se modifican, por lo tanto no pueden ser 50.","question":"¿La Gift «ボクシングスタイル» de hBP03-065〈戌神ころね〉 permite hacer que los HP restantes sean 50 al usar la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327（2025.03.11）"},{"answer":"No, no lo recibe. La habilidad 推しスキル “ぎゅっぎゅっ” de hBP01-001〈天音かなた〉 no es una habilidad que inflija daño, por lo tanto la habilidad de hBP01-116〈うぱお〉 no se activa.","question":"Si uso la habilidad 推しスキル “ぎゅっぎゅっ” de mi hBP01-001〈天音かなた〉 contra el holomen central del oponente que tiene anexado un hBP01-116〈うぱお〉, ¿mi holomen central recibe daño especial por la habilidad de hBP01-116〈うぱお〉?","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26（2024.09.21）"},{"answer":"No, no se puede. Como no inflige daño, no se puede usar la habilidad de la SP Oshi Skill «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la SP Oshi Skill «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"},{"answer":"No, no se puede. Como no inflige daño, no se puede usar la habilidad de hBP01-121〈Kotori〉 contra la habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la habilidad de hBP01-121〈Kotori〉 contra la habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24（2024.09.21）"},{"answer":"No, no se puede. Dado que no inflige daño, la habilidad de hBP01-117〈フレンド〉 no puede usarse contra la habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la habilidad de hBP01-117〈フレンド〉 contra la habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23（2024.09.21）"},{"answer":"No, no se puede. Como no inflige daño, no se puede usar la Gift «V.7» de hBP01-027〈ベスティア・ゼータ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la Gift «V.7» de hBP01-027〈ベスティア・ゼータ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22（2024.09.21）"},{"answer":"No, no se puede. La Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉 no inflige daño, por lo tanto no se puede usar la habilidad de la Oshi Skill «文明の守護者» de hBP01-002〈七詩ムメイ〉.","question":"Durante el turno del oponente, cuando un Holomen propio con #Promise tiene sus HP reducidos a 50 por la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉, ¿se puede usar la Oshi Skill «文明の守護者» de hBP01-002〈七詩ムメイ〉 para reducir en 50 el daño recibido?","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21（2024.09.21）"},{"answer":"No, no se activa. La habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉 especifica un valor de HP restante, no restaura HP.","question":"Se usó la habilidad oshi 「Apretujón, apretujón」 de hBP01-001〈天音かなた〉 sobre un holomen del oponente con HP restante 40 y equipado con 〈石の斧〉. Cuando su HP se convierte en 50, ¿se activa la habilidad de 〈石の斧〉 que dice ''cuando este holomen se recupera''?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20（2024.09.21）"},{"answer":"Los HP restantes del Holomen oponente se establecen en 50.","question":"Cuando se usa la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉 en un Holomen oponente con HP restantes de 40 o menos, ¿qué ocurre con sus HP?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19（2024.09.21）"},{"answer":"No, no se puede. La Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉 no inflige daño, así que no se puede reducir ni evitar el daño recibido.","question":"Cuando los HP de mi Holomen central se reducen a 50 por la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉, ¿puedo evitar el daño usando la Gift «V.7» de hBP01-027〈ベスティア・ゼータ〉?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18（2024.09.21）"}],"id":[{"answer":"Tidak, tidak bisa.","question":"Apakah mungkin membuat HP tersisa menjadi “50” untuk Buzz Holomen yang dipasangi hBP06-097〈カワイイスタジャン〉 dengan Skill Oshi “ぎゅっぎゅっ” dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"Tidak, karena tidak terjadi perubahan HP, maka tidak bisa menjadi ‘50’.","question":"Apakah gift ‘冷静沈着’ dari hBP04-024〈儒烏風亭らでん〉 bisa membuat sisa HP menjadi ‘50’ dengan menggunakan skill oshi hBP01-001〈天音かなた〉「Peluk erat erat」?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"Ya, bisa.","question":"hBP01-118〈あん肝〉 dipasang pada 〈ときのそら〉, lalu 〈ときのそら〉 tersebut menggunakan Skill Oshishi hBP01-001〈天音かなた〉 “ぎゅっぎゅっ”. Dalam kasus ini, dapatkah sisa HP 〈ときのそら〉 yang dipasangi hBP01-118〈あん肝〉 diatur menjadi \"50\"?","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362（2025.03.11）"},{"answer":"Tidak, karena tidak terjadi perubahan HP, maka tidak bisa menjadi ‘50’.","question":"Apakah gift ‘ボクシングスタイル’ dari hBP03-065〈戌神ころね〉 bisa membuat sisa HP menjadi ‘50’ dengan skill oshi hBP01-001〈天音かなた〉「Peluk erat erat」?","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327（2025.03.11）"},{"answer":"Tidak, tidak menerima. Karena kemampuan skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari hBP01-116〈うぱお〉 tidak akan aktif.","question":"Jika menggunakan skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 terhadap Holomen pusat lawan yang mengenakan hBP01-116〈うぱお〉, apakah Holomen pusat saya akan menerima damage spesial dari kemampuan hBP01-116〈うぱお〉?","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, maka kemampuan dari SP skill oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 tidak dapat digunakan terhadapnya.","question":"Apakah skill SP oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari hBP01-121〈Kotori〉 tidak dapat digunakan terhadapnya.","question":"Apakah kemampuan dari hBP01-121〈Kotori〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari hBP01-117〈フレンド〉 tidak dapat digunakan terhadapnya.","question":"Apakah kemampuan dari hBP01-117〈フレンド〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill “ぎゅっぎゅっ” dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, Gift “V.7” dari hBP01-027〈ベスティア・ゼータ〉 tidak dapat digunakan terhadapnya.","question":"Apakah Gift “V.7” dari hBP01-027〈ベスティア・ゼータ〉 dapat digunakan terhadap skill oshi “ぎゅっぎゅっ” dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22（2024.09.21）"},{"answer":"不行，不能。hBP01-001〈天音かなた〉的推し技能「Peluk erat erat」不是一個會造成傷害的能力，所以無法使用hBP01-002〈七詩ムメイ〉的推し技能能力。","question":"在對手的回合，當hBP01-001〈天音かなた〉的推し技能「Peluk erat erat」使自己帶有#Promise 的ホロメン剩餘HP變為50時，能否用hBP01-002〈七詩ムメイ〉的推し技能「Pelindung Peradaban」使該ホロメン的傷害-50？","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21（2024.09.21）"},{"answer":"Tidak, tidak akan aktif. Karena skill oshi〈天音かなた〉「Peluk erat erat」 hanya menetapkan nilai HP, bukan memulihkan HP.","question":"Jika skill oshi〈天音かなた〉「Peluk erat erat」 digunakan pada Holomen lawan yang memiliki sisa HP 40 dan mengenakan〈石の斧〉, ketika sisa HP menjadi 50, apakah kemampuan ‘Saat Holomen ini pulih’ dari〈石の斧〉 akan aktif?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20（2024.09.21）"},{"answer":"Sisa HP Holomen lawan menjadi 50.","question":"Jika skill oshi〈天音かなた〉「Peluk erat erat」 digunakan pada Holomen lawan yang memiliki sisa HP 40 atau kurang, bagaimana hasil HP-nya?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19（2024.09.21）"},{"answer":"Tidak, tidak bisa. Karena skill oshi〈天音かなた〉「Peluk erat erat」 bukan kemampuan yang memberikan damage, maka tidak dapat mengurangi atau menghindari damage dengan cara apa pun.","question":"Ketika skill oshi〈天音かなた〉「Peluk erat erat」 menurunkan HP Holomen tengah milikku menjadi 50, apakah gift ‘V.7’ dari〈ベスティア・ゼータ〉 dapat digunakan untuk menghindari damage?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18（2024.09.21）"}],"ja":[{"answer":"いいえ、できません。","question":"hBP06-097〈カワイイスタジャン〉が付いているBuzzホロメンを、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」によって残りHPを「50」させることはできますか？","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"いいえ、HPの変動はしないため「50」にはできません。","question":"hBP04-024〈儒烏風亭らでん〉のギフト「冷静沈着」は、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」によって残りHPを「50」させることはできますか？","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"はい、できます。","question":"hBP01-118〈あん肝〉が付いている〈ときのそら〉にhBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」を使いました。この場合、hBP01-118〈あん肝〉が付いている〈ときのそら〉の残りHPを「50」にできますか？","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362（2025.03.11）"},{"answer":"いいえ、HPの変動はしないため「50」にはできません。","question":"hBP03-065〈戌神ころね〉のギフト「ボクシングスタイル」は、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」によって残りHPを「50」にすることはできますか？","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327（2025.03.11）"},{"answer":"いいえ、受けません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」の能力はダメージを与える能力ではないため、hBP01-116〈うぱお〉の能力は発揮しません。","question":"hBP01-116〈うぱお〉が付いている相手のセンターホロメンに対してhBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」を使用した場合、自分のセンターホロメンは、相手のhBP01-116〈うぱお〉の能力で特殊ダメージを受けますか？","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-121〈Kotori〉の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-121〈Kotori〉の能力を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-117〈フレンド〉の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-117〈フレンド〉の能力を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22（2024.09.21）"},{"answer":"いいえ、できません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」はダメージを与える能力ではないため、hBP01-002〈七詩ムメイ〉の推しスキル「文明の守護者」の能力を使用することはできません。","question":"相手のターンで、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」で自分の#Promise を持つホロメンがの残りHPが50になる時、hBP01-002〈七詩ムメイ〉の推しスキル「文明の守護者」で、そのホロメンのダメージを-50することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21（2024.09.21）"},{"answer":"いいえ、発揮しません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」は残りHPを指定する能力のため、HPを回復していません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」を、残りHPが40で、〈石の斧〉が付いている相手のホロメンに使用しました。残りHPが50になった時、〈石の斧〉の「このホロメンが回復した時」の能力は発揮しますか？","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20（2024.09.21）"},{"answer":"相手のホロメンの残りのHPは50になります。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」は、残りのHPが40以下の相手のホロメンに使用した場合、HPはどうなりますか？","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19（2024.09.21）"},{"answer":"いいえ、できません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」は、ダメージを与える能力ではないため、受けるダメージを減らしたり、ダメージを受けないようにすることはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」で自分のセンターホロメンのHPを50に減らされる時、hBP01-027〈ベスティア・ゼータ〉のギフト「V.7」でダメージを受けないようにすることはできますか？","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18（2024.09.21）"}],"ko":[{"answer":"아니요, 할 수 없습니다.","question":"hBP06-097〈カワイイスタジャン〉이 장착된 Buzz 홀로멤버의 남은 HP를, hBP01-001〈天音かなた〉의 ‘오시 스킬 「꼬옥꼬옥」’에 의해 「50」으로 만들 수 있나요?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"아니요, HP의 변동이 일어나지 않기 