INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (168, 'hY01-001', 'hY01-001 はずき 白エール ■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。' || char(13) || '
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('172', 'hYS01-001', 'oshiCharacter', 'OC', NULL, 'hY01/hYS01-001_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hY01/hYS01-001_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '七詩ムメイ', '{"card_sets":["スタートエールセット"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Nanashi Mumei","oshi_skill":{"effect":"[Once per turn] During this turn, your white Collab holomem gets +20 Arts.","name":"WHITE BATON","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Usable during your opponent''s turn when your white holomem would take damage from your opponent: That 1 holomem takes -20 damage.","name":"Quick Guard","timing":"Once per game"}},"es":{"name":"Nanashi Mumei","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las artes de tu holomen de colaboración blanco obtienen +20.","name":"Bastón Blanco","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Puedes usar esto durante el turno de tu oponente, cuando uno de tus holomen blancos vaya a recibir daño del oponente: el daño que recibe ese holomen se reduce en 20.","name":"Guardia rápida","timing":"Una vez por partida"}},"id":{"name":"Nanashi Mumei","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts holomen collab putih milikmu +20.","name":"Baton Putih","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Dapat digunakan saat holomen putih milikmu akan menerima damage dari lawan pada giliran lawan: damage yang diterima 1 holomen itu -20.","name":"Penjagaan Cepat","timing":"Sekali per permainan"}},"ja":{"name":"七詩ムメイ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の白コラボホロメンのアーツ+20。","name":"ホワイトバトン","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]相手のターンで、自分の白ホロメンが相手からダメージを受ける時に使える:そのホロメン1人が受けるダメージ-20。","name":"クイックガード","timing":"ゲームに1回"}},"ko":{"name":"나나시 무메이","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안 자신의 흰 콜라보 홀로멘의 아츠+20.","name":"화이트 배턴","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]상대 턴에 자신의 흰 홀로멘이 상대에게서 대미지를 받을 때 사용할 수 있다: 그 홀로멘 1명이 받는 대미지-20.","name":"퀵 가드","timing":"게임에 1번"}},"tc":{"name":"七詩ムメイ","oshi_skill":{"effect":"[每回合1次]在這個回合期間，自己的白色合作holomen的藝術+20。","name":"白色接力棒","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]可在對手的回合中，自己的白色holomen將受到對手傷害時使用：那1名holomen將受到的傷害-20。","name":"快速防禦","timing":"每場對戰1次"}},"th":{"name":"นานาชิ มุเมอิ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของโคลาโบโฮโลเมนสีขาวของคุณ +20","name":"กระบองสีขาว","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ใช้ได้ในเทิร์นของคู่แข่ง เมื่อโฮโลเมนสีขาวของคุณจะได้รับแดเมจจากคู่แข่ง: แดเมจที่โฮโลเมนนั้น 1 คนจะได้รับ -20","name":"การ์ดป้องกันฉับไว","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{"en":[{"answer":"No, you cannot. Since it does not deal damage, you cannot use hYS01-001〈七詩ムメイ〉’s SP oshi skill “Quick Guard” against hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”.","question":"Can you use hYS01-001〈七詩ムメイ〉’s SP oshi skill “Quick Guard” in response to hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25 (2024.09.21)"}],"es":[{"answer":"No, no se puede. Como no inflige daño, no se puede usar la habilidad de la SP Oshi Skill «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la SP Oshi Skill «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"id":[{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, maka kemampuan dari SP skill oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 tidak dapat digunakan terhadapnya.","question":"Apakah skill SP oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"ja":[{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"ko":[{"answer":"아니요, 사용할 수 없습니다. 데미지를 주는 능력이 아니기 때문에, hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「퀵 가드」의 능력을 사용할 수 없습니다.","question":"hBP01-001〈天音かなた〉의 오시 스킬〈꽉꽉〉에 대해 hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「퀵 가드」를 사용할 수 있나요?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"tc":[{"answer":"不，可以使用。由於該技能不是造成傷害的能力，因此無法對 hBP01-001〈天音かなた〉的推し技能「緊緊抱抱」使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」的效果。","question":"可以對 hBP01-001〈天音かなた〉的推し技能〈ぎゅっぎゅっ〉使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」嗎？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"th":[{"answer":"ไม่ได้ ไม่สามารถใช้ได้ เนื่องจากสกิลโอชิ “ぎゅっぎゅっ” ของ hBP01-001〈天音かなた〉 ไม่ใช่ความสามารถที่สร้างความเสียหาย จึงไม่สามารถใช้ความสามารถของ “クイックガード” ของ〈七詩ムメイ〉ได้","question":"สามารถใช้สกิล SP โอชิ “クイックガード” ของ hYS01-001〈七詩ムメイ〉 เพื่อตอบสนองต่อสกิลโอชิ〈ぎゅっぎゅっ〉ของ hBP01-001〈天音かなた〉 ได้ไหม?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}]}', '99e2403d08ac7a1b39de920fec79fa4ef55b5ce86ce286272a0f06eb92706ed4', '89649c6ff5f14f89173c984d60613aa66f60c395858121bdcff5369d9a65f670', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white', '172');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートエールセット', '172');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (172, 'hYS01-001', 'hYS01-001 松尾 省吾 七詩ムメイ ホワイトバトン [ターンに1回]このターンの間、自分の白コラボホロメンのアーツ+20。 クイックガード [ゲームに1回]相手のターンで、自分の白ホロメンが相手からダメージを受ける時に使える:そのホロメン1人が受けるダメージ-20。 Nanashi Mumei WHITE BATON [Once per turn] During this turn, your white Collab holomem gets +20 Arts. Quick Guard [Once per game] Usable during your opponent''s turn when your white holomem would take damage from your opponent: That 1 holomem takes -20 damage. 七詩ムメイ 白色接力棒 [每回合1次]在這個回合期間，自己的白色合作holomen的藝術+20。 快速防禦 [每場對戰1次]可在對手的回合中，自己的白色holomen將受到對手傷害時使用：那1名holomen將受到的傷害-20。 Nanashi Mumei Baton Putih [Sekali per giliran] Selama giliran ini, Arts holomen collab putih milikmu +20. Penjagaan Cepat [Sekali per permainan] Dapat digunakan saat holomen putih milikmu akan menerima damage dari lawan pada giliran lawan: damage yang diterima 1 holomen itu -20. 나나시 무메이 화이트 배턴 [턴에 1번]이번 턴 동안 자신의 흰 콜라보 홀로멘의 아츠+20. 퀵 가드 [게임에 1번]상대 턴에 자신의 흰 홀로멘이 상대에게서 대미지를 받을 때 사용할 수 있다: 그 홀로멘 1명이 받는 대미지-20. นานาชิ มุเมอิ กระบองสีขาว [ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของโคลาโบโฮโลเมนสีขาวของคุณ +20 การ์ดป้องกันฉับไว [ใช้ได้ 1 ครั้งต่อเกม] ใช้ได้ในเทิร์นของคู่แข่ง เมื่อโฮโลเมนสีขาวของคุณจะได้รับแดเมจจากคู่แข่ง: แดเมจที่โฮโลเมนนั้น 1 คนจะได้รับ -20 Nanashi Mumei Bastón Blanco [Una vez por turno] Durante este turno, las artes de tu holomen de colaboración blanco obtienen +20. Guardia rápida [Una vez por partida] Puedes usar esto durante el turno de tu oponente, cuando uno de tus holomen blancos vaya a recibir daño del oponente: el daño que recibe ese holomen se reduce en 20.', 'Q25（2024.09.21） hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？ いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。 Q25 (2024.09.21) Can you use hYS01-001〈七詩ムメイ〉’s SP oshi skill “Quick Guard” in response to hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”? No, you cannot. Since it does not deal damage, you cannot use hYS01-001〈七詩ムメイ〉’s SP oshi skill “Quick Guard” against hBP01-001〈天音かなた〉’s oshi skill “Gyuggyu”. Q25（2024.09.21） 可以對 hBP01-001〈天音かなた〉的推し技能〈ぎゅっぎゅっ〉使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」嗎？ 不，可以使用。由於該技能不是造成傷害的能力，因此無法對 hBP01-001〈天音かなた〉的推し技能「緊緊抱抱」使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」的效果。 Q25（2024.09.21） Apakah skill SP oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉? Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, maka kemampuan dari SP skill oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 tidak dapat digunakan terhadapnya. Q25（2024.09.21） hBP01-001〈天音かなた〉의 오시 스킬〈꽉꽉〉에 대해 hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「퀵 가드」를 사용할 수 있나요? 아니요, 사용할 수 없습니다. 데미지를 주는 능력이 아니기 때문에, hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「퀵 가드」의 능력을 사용할 수 없습니다. Q25（2024.09.21） สามารถใช้สกิล SP โอชิ “クイックガード” ของ hYS01-001〈七詩ムメイ〉 เพื่อตอบสนองต่อสกิลโอชิ〈ぎゅっぎゅっ〉ของ hBP01-001〈天音かなた〉 ได้ไหม? ไม่ได้ ไม่สามารถใช้ได้ เนื่องจากสกิลโอชิ “ぎゅっぎゅっ” ของ hBP01-001〈天音かなた〉 ไม่ใช่ความสามารถที่สร้างความเสียหาย จึงไม่สามารถใช้ความสามารถของ “クイックガード” ของ〈七詩ムメイ〉ได้ Q25（2024.09.21） ¿Se puede usar la SP Oshi Skill «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉? No, no se puede. Como no inflige daño, no se puede usar la habilidad de la SP Oshi Skill «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la Oshi Skill «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('446', 'hSD03-009', 'character', 'SR', 'second', 'hBP02/hSD03-009_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hSD03-009_SR.png', 190, NULL, 2, '["null","null"]', '江田藤', '猫又おかゆ', '{"arts":[{"cost_types":["blue","null"],"damage":60,"special_targets":["white"],"special_values":[50]},{"cost_types":["blue","blue","null","null"],"damage":100,"special_targets":["white"],"special_values":[50]}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["blue"],"translations":{"en":{"arts":[{"name":"MOGMOG"},{"effect":"You may archive 2 of this holomem''s Blue Cheer: Deal 30 special damage to the opponent''s Center holomem and 1 of their Back holomem.","name":"Okayu~"}],"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"name":"MOGMOG"},{"effect":"Puedes archivar 2 Blue Cheer de este holomen: inflige 30 de daño especial al holomen del Centro de tu oponente y a 1 holomen de la Retaguardia.","name":"Okayu~"}],"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"name":"MOGMOG"},{"effect":"Kamu boleh Archive 2 Yell Biru dari holomen ini: berikan Special Damage 30 kepada Center holomen lawan dan 1 Back holomen lawan.","name":"Okayu～"}],"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"name":"MOGMOG"},{"effect":"このホロメンの青エール2枚をアーカイブできる:相手のセンターホロメンとバックホロメン1人に特殊ダメージ30を与える。","name":"おかゆ～"}],"name":"猫又おかゆ","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"name":"MOGMOG"},{"effect":"이 홀로멤의 블루 옐 2장을 아카이브할 수 있다: 상대의 센터 홀로멤과 백 홀로멤 1명에게 특수 대미지 30을 준다.","name":"오카유~"}],"name":"네코마타 오카유","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"name":"MOGMOG"},{"effect":"可將此Holo成員的2張藍色應援存入存檔區：對對手的中心Holo成員與1位後備Holo成員造成特殊傷害30。","name":"粥粥～"}],"name":"貓又小粥","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"name":"ม็อกม็อก"},{"effect":"สามารถอาร์ไคฟ์ เยลสีน้ำเงิน 2 ใบของโฮโลเมนนี้ได้: สร้างความเสียหายพิเศษ 30 ให้แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามและแบ็คโฮโลเมน 1 คน","name":"โอคายู~"}],"name":"เนโกะมาตะ โอกายุ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', 'c1ae9bacbe7dd2178b23c724f9a9b72bd328fd2dfafdfbf4911f253a34613297', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
