INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (446, 'hSD03-009', 'hSD03-009 江田藤 JP ゲーマーズ ケモミミ 猫又おかゆ #JP #ゲーマーズ #ケモミミ MOGMOG おかゆ～ このホロメンの青エール2枚をアーカイブできる:相手のセンターホロメンとバックホロメン1人に特殊ダメージ30を与える。 Nekomata Okayu #JP #Gamers #Animal Ears MOGMOG Okayu~ You may archive 2 of this holomem''s Blue Cheer: Deal 30 special damage to the opponent''s Center holomem and 1 of their Back holomem. 貓又小粥 #JP #Gamers #獸耳 MOGMOG 粥粥～ 可將此Holo成員的2張藍色應援存入存檔區：對對手的中心Holo成員與1位後備Holo成員造成特殊傷害30。 Nekomata Okayu #JP #Gamers #Telinga Hewan MOGMOG Okayu～ Kamu boleh Archive 2 Yell Biru dari holomen ini: berikan Special Damage 30 kepada Center holomen lawan dan 1 Back holomen lawan. 네코마타 오카유 #JP #게이머즈 #수인귀 MOGMOG 오카유~ 이 홀로멤의 블루 옐 2장을 아카이브할 수 있다: 상대의 센터 홀로멤과 백 홀로멤 1명에게 특수 대미지 30을 준다. เนโกะมาตะ โอกายุ #JP #เกมเมอร์ส #หูสัตว์ ม็อกม็อก โอคายู~ สามารถอาร์ไคฟ์ เยลสีน้ำเงิน 2 ใบของโฮโลเมนนี้ได้: สร้างความเสียหายพิเศษ 30 ให้แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามและแบ็คโฮโลเมน 1 คน Nekomata Okayu #JP #Gamers #Animal Ears MOGMOG Okayu~ Puedes archivar 2 Blue Cheer de este holomen: inflige 30 de daño especial al holomen del Centro de tu oponente y a 1 holomen de la Retaguardia.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('447', 'hSD04-009', 'character', 'SR', 'second', 'hBP02/hSD04-009_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hSD04-009_SR.png', 190, NULL, 1, '["null"]', 'saihate', '癒月ちょこ', '{"arts":[{"cost_types":["purple","null"],"damage":50,"special_targets":["green"],"special_values":[50]},{"cost_types":["purple","purple","null"],"damage":60,"is_plus":true,"special_targets":["green"],"special_values":[50]}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"translations":{"en":{"arts":[{"name":"33... 22... 11..."},{"effect":"This Arts gains +40 for each Event you used this turn.","name":"Aku-tto"}],"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"name":"33… 22… 11…"},{"effect":"Esta Art +40 por cada 1 Evento que hayas usado este turno.","name":"Akutto"}],"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"name":"33… 22… 11…"},{"effect":"Untuk tiap 1 Event yang telah kamu gunakan pada giliran ini, Arts ini +40.","name":"Akutto"}],"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"name":"33… 22… 11…"},{"effect":"このターンに自分が使っていたイベント1枚につき、このアーツ+40。","name":"あくとっ"}],"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"name":"33… 22… 11…"},{"effect":"이번 턴에 자신이 사용한 이벤트 1장당, 이 아츠+40.","name":"아쿠톳"}],"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"name":"33… 22… 11…"},{"effect":"這個回合自己每使用過1張活動卡，這個藝術便+40。","name":"Acutto"}],"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"name":"33… 22… 11…"},{"effect":"อาร์ตนี้ +40 ต่ออีเวนต์ 1 ใบที่คุณได้ใช้ในเทิร์นนี้","name":"อาคุตต์"}],"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', '322597265a657c0fccc90d3b53b8b0637a5bd0932da73bdc96481accde76cc27', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
