INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (447, 'hSD04-009', 'hSD04-009 saihate JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ このターンに自分が使っていたイベント1枚につき、このアーツ+40。 Yuzuki Choco #JP #2nd Gen #Cooking 33... 22... 11... Aku-tto This Arts gains +40 for each Event you used this turn. 癒月巧可 #JP #2期生 #料理 33… 22… 11… Acutto 這個回合自己每使用過1張活動卡，這個藝術便+40。 Yuzuki Choco #JP #Gen 2 #Masakan 33… 22… 11… Akutto Untuk tiap 1 Event yang telah kamu gunakan pada giliran ini, Arts ini +40. 유즈키 초코 #JP #2기생 #요리 33… 22… 11… 아쿠톳 이번 턴에 자신이 사용한 이벤트 1장당, 이 아츠+40. ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร 33… 22… 11… อาคุตต์ อาร์ตนี้ +40 ต่ออีเวนต์ 1 ใบที่คุณได้ใช้ในเทิร์นนี้ Yuzuki Choco #JP #2nd Gen #Cooking 33… 22… 11… Akutto Esta Art +40 por cada 1 Evento que hayas usado este turno.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('477', 'hY01-003', 'supportCheer', 'SY', NULL, 'hBP02/hY01-003_SY', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hY01-003_SY.png', NULL, NULL, NULL, NULL, 'リズ', '白エール', '{"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["white"],"translations":{"en":{"ability_text":"■ When a holomem leaves the Stage, Archive all Cheer attached to that holomem.\n■ When a holomem uses Baton Touch, Archive the specified number of Cheer attached to that holomem.","name":"White Cheer"},"es":{"ability_text":"■Cuando un holomen deja el Stage, archiva todos los Cheer de ese holomen.\n■Cuando un holomen hace Baton Touch, archiva la cantidad de Cheer especificada de ese holomen.","name":"White Cheer"},"id":{"ability_text":"■Saat holomen meninggalkan Stage, Archive semua Cheer pada holomen itu.\n■Saat holomen melakukan Baton Touch, Archive sejumlah Cheer yang ditentukan pada holomen itu.","name":"Yell Putih"},"ja":{"ability_text":"■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。\r\n■ホロメンがバトンタッチする時、そのホロメンのエールを指定された枚数アーカイブする。","name":"白エール"},"ko":{"ability_text":"■홀로멘이 스테이지를 떠날 때, 그 홀로멘의 에일 전부를 아카이브한다.\n■홀로멘이 Baton Touch할 때, 그 홀로멘의 에일을 지정된 장수만큼 아카이브한다.","name":"화이트 옐"},"tc":{"ability_text":"■當holomen離開舞台時，將該holomen的所有應援存檔。\n■當holomen進行Baton Touch時，將該holomen指定數量的應援存檔。","name":"白色應援"},"th":{"ability_text":"■เมื่อโฮโลเม็มออกจาก Stage ให้ Archive เยลทั้งหมดของโฮโลเม็มนั้น\n■เมื่อโฮโลเม็ม Baton Touch ให้ Archive เยลของโฮโลเม็มนั้นตามจำนวนที่กำหนด","name":"เยลสีขาว"}}}', '{}', 'fd3ff96a3682be9679861592956a5d5c4cdda174a32efd397834d46c7338c6fc', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
