INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (477, 'hY01-003', 'hY01-003 リズ 白エール ■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。' || char(13) || '
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('529', 'hSD05-013', 'character', 'U', 'debut', 'hSD05/hSD05-013_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD05/hSD05-013_U.png', 90, NULL, 1, '["null"]', 'Watersnake', '音乃瀬奏', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["スタートデッキ 白 轟はじめ"],"color_codes":["yellow"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Gaha w"}],"keyword":{"effect":"You may move 1 Cheer on your Stage to one of your holomem other than this holomem.","name":"Crescendo Days"},"name":"Otonose Kanade","tags":["#DEV_IS","#ReGLOSS","#Singing"]},"es":{"arts":[{"name":"Gaha w"}],"keyword":{"effect":"Puedes recolocar 1 Cheer de tu escenario en uno de tus holomen que no sea este holomen.","name":"Días de crescendo"},"name":"Otonose Kanade","tags":["#DEV_IS","#ReGLOSS","#Singing"]},"id":{"arts":[{"name":"Gaha w"}],"keyword":{"effect":"Kamu boleh memindahkan 1 Cheer di Stage milikmu ke Holomen milikmu selain Holomen ini.","name":"Hari-hari yang kian crescendo"},"name":"Otonose Kanade","tags":["#DEV_IS","#ReGLOSS","#Menyanyi"]},"ja":{"arts":[{"name":"ガハw"}],"keyword":{"effect":"自分のステージのエール1枚を、このホロメン以外の自分のホロメンに付け替えられる。","name":"クレッシェンドな日々"},"name":"音乃瀬奏","tags":["#DEV_IS","#ReGLOSS","#歌"]},"ko":{"arts":[{"name":"가하w"}],"keyword":{"effect":"자신의 스테이지의 엘 1장을 이 홀로멤 이외의 자신의 홀로멤으로 다시 붙일 수 있다.","name":"크레셴도한 나날"},"name":"오토노세 카나데","tags":["#DEV_IS","#ReGLOSS","#노래"]},"tc":{"arts":[{"name":"嘎哈w"}],"keyword":{"effect":"可以將自己舞台上的1張應援改附到自己其他Holomen上，但不能附給這位Holomen。","name":"漸強的每一天"},"name":"音乃瀨奏","tags":["#DEV_IS","#ReGLOSS","#歌唱"]},"th":{"arts":[{"name":"กาฮะw"}],"keyword":{"effect":"คุณสามารถย้ายเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนอีกคนของคุณที่ไม่ใช่โฮโลเมนนี้","name":"วันเวลาที่ค่อยๆ เร่งเร้าดั่งเครสเชนโด"},"name":"โอโตโนเซะ คานาเดะ","tags":["#DEV_IS","#ReGLOSS","#เพลง"]}}}', '{}', '932a067020f974b78dcf985eb14f7d25158b1d8ae47b8b2f6c6bbcc8c067ff12', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
