INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (529, 'hSD05-013', 'hSD05-013 Watersnake DEV_IS ReGLOSS 歌 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 自分のステージのエール1枚を、このホロメン以外の自分のホロメンに付け替えられる。 Otonose Kanade #DEV_IS #ReGLOSS #Singing Gaha w Crescendo Days You may move 1 Cheer on your Stage to one of your holomem other than this holomem. 音乃瀨奏 #DEV_IS #ReGLOSS #歌唱 嘎哈w 漸強的每一天 可以將自己舞台上的1張應援改附到自己其他Holomen上，但不能附給這位Holomen。 Otonose Kanade #DEV_IS #ReGLOSS #Menyanyi Gaha w Hari-hari yang kian crescendo Kamu boleh memindahkan 1 Cheer di Stage milikmu ke Holomen milikmu selain Holomen ini. 오토노세 카나데 #DEV_IS #ReGLOSS #노래 가하w 크레셴도한 나날 자신의 스테이지의 엘 1장을 이 홀로멤 이외의 자신의 홀로멤으로 다시 붙일 수 있다. โอโตโนเซะ คานาเดะ #DEV_IS #ReGLOSS #เพลง กาฮะw วันเวลาที่ค่อยๆ เร่งเร้าดั่งเครสเชนโด คุณสามารถย้ายเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนอีกคนของคุณที่ไม่ใช่โฮโลเมนนี้ Otonose Kanade #DEV_IS #ReGLOSS #Singing Gaha w Días de crescendo Puedes recolocar 1 Cheer de tu escenario en uno de tus holomen que no sea este holomen.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('614', 'hBP03-050', 'character', 'R', 'first', 'hBP03/hBP03-050_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-050_R.png', 150, NULL, 1, '["null"]', '© 2016 COVER Corp. MariA', 'FUWAMOCO', '{"arts":[{"cost_types":["null","null"],"damage":40},{"cost_types":["blue","red"],"damage":60}],"card_sets":["ブースターパック「エリートスパーク」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue","red"],"translations":{"en":{"arts":[{"effect":"Reveal 1 [Red Cheer or Blue Cheer] from your Cheer Deck, and send it to your holomem with #Advent. Then shuffle your Cheer Deck.","name":"Sisters of the Demon Realm’s Guard Dogs"},{"name":"Together, We''re FUWAMOCO!"}],"extra":"This holomem is also treated as 〈Fuwawa Abyssgard〉 and 〈Mococo Abyssgard〉.","name":"FUWAMOCO","tags":["#EN","#Advent","#Animal Ears"]},"es":{"arts":[{"effect":"Revela 1 carta de [Red CheerかBlue Cheer] de tu Mazo de Cheer y envíala a un holomem tuyo con #Advent. Después baraja tu Mazo de Cheer.","name":"Las hermanas sabueso infernal"},{"name":"¡Juntas somos FUWAMOCO!"}],"extra":"Este holomen también se considera como 〈Fuwawa Abyssgard〉 y 〈Mococo Abyssgard〉","name":"FUWAMOCO","tags":["#EN","#Advent","#Animal Ears"]},"id":{"arts":[{"effect":"Ungkapkan 1 kartu [Yell MerahかYell Biru] dari Cheer Deck milikmu, lalu kirim kepada holomen milikmu yang memiliki #Advent. Lalu kocok Cheer Deck.","name":"Saudari Anjing Penjaga Dunia Iblis"},{"name":"Bersama berdua, kami adalah FUWAMOCO!"}],"extra":"Holomen ini juga diperlakukan sebagai 〈Fuwawa Abyssgard〉〈Mococo Abyssgard〉","name":"FUWAMOCO","tags":["#EN","#Advent","#Telinga Hewan"]},"ja":{"arts":[{"effect":"自分のエールデッキから、[赤エールか青エール]1枚を公開し、自分の#Adventを持つホロメンに送る。そしてエールデッキをシャッフルする。","name":"魔界乃番犬シスターズ"},{"name":"2人揃ってFUWAMOCOです！"}],"extra":"このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"ko":{"arts":[{"effect":"자신의 에일 덱에서 [레드 옐か블루 옐] 1장을 공개해, 자신의 #Advent를 가진 홀로멘에게 보낸다. 그리고 에일 덱을 셔플한다.","name":"마계의 번견 시스터즈"},{"name":"둘이서 함께 FUWAMOCO입니다!"}],"extra":"이 홀로멤은 〈후와와 어비스가드〉 〈모코코 어비스가드〉로도 취급한다","name":"FUWAMOCO","tags":["#EN","#Advent","#수인귀"]},"tc":{"arts":[{"effect":"從自己的應援牌庫公開[紅色應援或藍色應援]1張，附加到自己持有#Advent的Holo成員上。然後將應援牌庫洗牌。","name":"魔界看門犬姐妹"},{"name":"我們兩個合起來就是FUWAMOCO！"}],"extra":"此Holo成員也視為〈Fuwawa Abyssguard〉〈Mococo Abyssguard〉","name":"FUWAMOCO","tags":["#EN","#Advent","#獸耳"]},"th":{"arts":[{"effect":"เปิดเผย [เยลสีแดงหรือเยลสีน้ำเงิน] 1 ใบจากเด็คพลังงานของคุณ แล้วส่งไปให้โฮโลเมนของคุณที่มี #Advent จากนั้นสับเด็คพลังงาน","name":"พี่น้องสุนัขเฝ้าแห่งโลกปีศาจ"},{"name":"พวกเราสองคนคือ FUWAMOCO ค่ะ!"}],"extra":"โฮโลเมมเบอร์นี้ให้นับเป็น〈ฟุวาวา อะบิสการ์ด〉〈โมโคโคะ อะบิสการ์ด〉ได้ด้วย","name":"FUWAMOCO","tags":["#EN","#Advent","#หูสัตว์"]}}}', '{"en":[{"answer":"It means this card is considered to have the card names 〈フワワ・アビスガード〉, 〈モココ・アビスガード〉, and 〈FUWAMOCO〉.","question":"What does the extra ability of hBP03-050 〈FUWAMOCO〉 — “This Holomen is also treated as 〈フワワ・アビスガード〉 and 〈モココ・アビスガード〉.” — mean?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"Yes, it does.","question":"Does the extra ability of hBP03-050 〈FUWAMOCO〉 — “This Holomen is also treated as 〈フワワ・アビスガード〉 and 〈モココ・アビスガード〉.” — apply even when it’s not on the stage?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"Yes, you can.","question":"When using hBP04-089〈ツートンカラーパソコン〉, I chose 〈ときのそら〉 and 〈フワワ・アビスガード〉 on my Stage as the two Holomen with different single colors. In this case, can I add hSD01-013〈SorAZ〉 and hBP03-050〈FUWAMOCO〉 to my hand as the 1st Holomen of the same colors as the chosen Holomen?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404 (2025.06.11)"},{"answer":"Yes, it does.","question":"For hBP04-049〈ムーナ・ホシノヴァ〉’s Arts “Shining Moon,” does it still get “+50” if the only other Holomen on your stage is hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP04-049","hBP03-050"],"raw_html":"[hBP04-049 ： ムーナ・ホシノヴァ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q390（2025.06.11）"},{"answer":"Yes, you can. Even if there isn’t a card with that exact name, if an Extra card states something like “This Holomen is also treated as 〈Fuwawa Abyssgard〉 and 〈Mococo Abyssgard〉,” that condition is fulfilled.","question":"For hBP03-109 〈Ruffians〉, the effect “You may send a blue Cheer from your Archive to your 〈Fuwawa Abyssgard〉” — can this also be sent to hBP03-050 〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-109","hBP03-050","hBP03-043"],"raw_html":"[hBP03-109 ： Ruffians]\n[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q359 (2025.03.11)"},{"answer":"Yes, you can. hBP03-050〈FUWAMOCO〉 is both red and blue, so it meets the condition.","question":"If my Oshi Holomen is hBP03-004〈FUWAMOCO〉, can I add hBP03-050〈FUWAMOCO〉 to my hand using hBP03-084〈ゴージャスパソコン〉?","related_cards":{"card_number":["hBP03-050","hBP03-084","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-084 ： ゴージャスパソコン]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q340 (2025.03.11)"},{"answer":"Yes, you can. Even if the specific card name isn’t present, if a card has an extra that treats it as a specific name (such as “This Holomen is also treated as 〈フワワ・アビスガード〉 and 〈モココ・アビスガード〉.”), it satisfies that condition.","question":"Using the art “Want to eat together?” from hBP03-043 〈フワワ・アビスガード〉, can I transfer an Aile to my hBP03-050 〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-043"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q322（2025.03.11）"},{"answer":"Yes, it does. Even if the specific card name isn’t among your cards, if a card has an extra that treats it as a certain name, it fulfills that condition.","question":"Does the art “もこもこしてる方” from hBP03-039 〈モココ・アビスガード〉 still give +30 if my center Holomen is hBP03-050 〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q321（2025.03.11）"},{"answer":"Yes, it can. Even if there isn’t a card with the corresponding name, if there is a card in Extra that says something like “This Holomen is also treated as 〈フワワ・アビスガード〉〈モココ・アビスガード〉,” it fulfills the condition.","question":"Can hBP03-042〈フワワ・アビスガード〉’s Bloom Effect “Fuwahana Flowing Stream” deal 20 Special Damage even if the only other Holomen on my Stage is hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-042","hBP03-050"],"raw_html":"[hBP03-042 ： フワワ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q320 (2025.03.11)"},{"answer":"Yes, it moves without resting. Even if the card name itself does not include the specified one, if an Extra effect states something like “This Holomen is also treated as 〈フワワ・アビスガード〉 and 〈モココ・アビスガード〉,” it fulfills the condition.","question":"For hBP03-039 〈モココ・アビスガード〉’s gift “魔界乃番犬の暴れん坊”, does it still move to the back position without resting if my center Holomen is hBP03-050 〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q319 (2025.03.11)"},{"answer":"Yes, you can. Even if there is no card that exactly matches the name, if a card in the Extra area has an effect stating something like “This Holomem is also treated as 〈フワワ・アビスガード〉 and 〈モココ・アビスガード〉,” then it fulfills the condition.","question":"With the Bloom effect “It’s Playtime!” of hBP03-038〈モココ・アビスガード〉, can I add hBP03-050〈FUWAMOCO〉 from my deck to my hand?","related_cards":{"card_number":["hBP03-050","hBP03-038"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-038 ： モココ・アビスガード]"},"title":"Q318 (2025.03.11)"},{"answer":"Yes, you can. Even if the specific name isn’t among your cards, cards with extras that treat them as certain names count as fulfilling that condition.","question":"With hBP03-004 〈FUWAMOCO〉’s Oshi Skill “モコちゃん！”, can I send an Aile to my hBP03-050 〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q302（2025.03.11）"}],"es":[{"answer":"Significa que tiene los nombres de carta 〈フワワ・アビスガード〉, 〈モココ・アビスガード〉 y 〈FUWAMOCO〉.","question":"¿Qué significa la habilidad extra de hBP03-050〈FUWAMOCO〉 «Este holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉»?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"Sí, se considera así en todas las zonas.","question":"Con respecto al Extra de hBP03-050〈FUWAMOCO〉 «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», ¿se considera así incluso cuando no está en el escenario?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"Sí, puedes hacerlo.","question":"Usando hBP04-089〈ツートンカラーパソコン〉, elegí como holomen de colores diferentes en mi escenario a 〈ときのそら〉 y 〈フワワ・アビスガード〉. En este caso, ¿puedo añadir a mi mano a hSD01-013〈SorAZ〉 y a hBP03-050〈FUWAMOCO〉 como holomen 1st del mismo color que los elegidos?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Sí, se activa.","question":"¿La habilidad de la carta de arte «Shining Moon» de hBP04-049〈ムーナ・ホシノヴァ〉 se activa con «+50» incluso si el único Holomen aliado es hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP04-049","hBP03-050"],"raw_html":"[hBP04-049 ： ムーナ・ホシノヴァ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q390（2025.06.11）"},{"answer":"Sí, se puede. Incluso si una carta no tiene el nombre mencionado, si existe una carta que en su texto Extra indique algo como “Esta Holomen también se considera como 〈フワワ・アビスガード〉 o 〈モココ・アビスガード〉”, cumple con esa condición.","question":"En la carta hBP03-109〈Ruffians〉 se indica: “Puedes enviar un Cheer azul de tu archivo a tu 〈フワワ・アビスガード〉.” ¿También se puede enviar a hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-109","hBP03-050","hBP03-043"],"raw_html":"[hBP03-109 ： Ruffians]\n[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q359（2025.03.11）"},{"answer":"Sí, puedes. hBP03-050〈FUWAMOCO〉 es tanto roja como azul, por lo que cumple la condición.","question":"Si mi holomen favorito es hBP03-004〈FUWAMOCO〉, ¿puedo añadir hBP03-050〈FUWAMOCO〉 a mi mano con hBP03-084〈ゴージャスパソコン〉?","related_cards":{"card_number":["hBP03-050","hBP03-084","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-084 ： ゴージャスパソコン]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q340（2025.03.11）"},{"answer":"Sí, se puede. Incluso si una carta no tiene el nombre mencionado, si existe una carta que en su texto Extra indique algo como “Esta Holomen también se considera como 〈フワワ・アビスガード〉 o 〈モココ・アビスガード〉”, cumple con esa condición.","question":"En la habilidad “¿Comemos juntas?” del arte de hBP03-043〈フワワ・アビスガード〉, ¿puedo cambiar un Cheer de esta carta a mi hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-043"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q322（2025.03.11）"},{"answer":"Sí, se incrementa. Aunque la carta no tenga el mismo nombre, si cuenta con un Extra que indique «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», se considera válida.","question":"Si mi Holomen central es hBP03-050〈FUWAMOCO〉, ¿el arte «モコモコしてる方» de hBP03-039〈モココ・アビスガード〉 se incrementa en «+30»?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q321（2025.03.11）"},{"answer":"Sí, puedes infligirlo. Incluso si la carta no tiene ese nombre, el Extra de 〈FUWAMOCO〉 cumple la condición mencionada.","question":"En el efecto Bloom «フワ花流水» de hBP03-042〈フワワ・アビスガード〉, ¿si mi único Holomen en el escenario es hBP03-050〈FUWAMOCO〉, puedo infligir daño especial de «20»?","related_cards":{"card_number":["hBP03-042","hBP03-050"],"raw_html":"[hBP03-042 ： フワワ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q320（2025.03.11）"},{"answer":"Sí, se mueve sin descansar. Si la carta tiene el Extra que la hace contar como los nombres 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉, cumple la condición.","question":"Si mi Holomen central es hBP03-050〈FUWAMOCO〉, ¿el regalo «Rebelde Guardiana del Inframundo» de hBP03-039〈モココ・アビスガード〉 se mueve a la posición trasera sin descansar?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q319（2025.03.11）"},{"answer":"Sí, se puede. Aunque el nombre no coincida directamente, si tiene la habilidad extra «Este holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», cumple con la condición.","question":"¿Con la habilidad del efecto Bloom «¡Hora de jugar!» de hBP03-038〈モココ・アビスガード〉 se puede añadir hBP03-050〈FUWAMOCO〉 a la mano desde el mazo?","related_cards":{"card_number":["hBP03-050","hBP03-038"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-038 ： モココ・アビスガード]"},"title":"Q318（2025.03.11）"},{"answer":"Sí, puede. Incluso si no hay una carta con ese nombre exacto, mientras exista una carta en Extra que diga algo como «Este Holomen también se considera como 〈フワワ・アビスガード〉 o 〈モココ・アビスガード〉», se cumple la condición.","question":"¿La habilidad Oshi «¡Moco-chan!» de hBP03-004〈FUWAMOCO〉 puede enviar apoyo a tu hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q302（2025.03.11）"}],"id":[{"answer":"Itu berarti kartu ini memiliki nama〈フワワ・アビスガード〉,〈モココ・アビスガード〉, dan〈FUWAMOCO〉sebagai nama kartu.","question":"Apa arti dari kemampuan ekstra “Holomen ini juga dianggap sebagai〈フワワ・アビスガード〉dan〈モココ・アビスガード〉” pada hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"Ya, tetap dianggap demikian.","question":"Apakah kemampuan ekstra “Holomen ini juga dianggap sebagai 〈フワワ・アビスガード〉 dan 〈モココ・アビスガード〉” dari hBP03-050〈FUWAMOCO〉 juga berlaku ketika tidak berada di stage?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"Ya, boleh menambahkannya.","question":"Saat menggunakan hBP04-089〈ツートンカラーパソコン〉, saya memilih 〈ときのそら〉 dan 〈フワワ・アビスガード〉 sebagai dua Holomen di panggung saya yang masing-masing hanya memiliki 1 warna dan warnanya berbeda. Dalam kasus ini, apakah saya bisa menambah hSD01-013〈SorAZ〉 dan hBP03-050〈FUWAMOCO〉 sebagai 1st Holomen yang warnanya sama dengan Holomen yang dipilih ke tangan saya?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Ya, akan ditambahkan.","question":"hBP04-049〈ムーナ・ホシノヴァ〉のアーツ「Shining Moon」の能力は、自分の他のホロメンがhBP03-050〈FUWAMOCO〉のみでも「+50」されますか？","related_cards":{"card_number":["hBP04-049","hBP03-050"],"raw_html":"[hBP04-049 ： ムーナ・ホシノヴァ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q390（2025.06.11）"},{"answer":"Ya, bisa. Walaupun nama kartu tidak secara langsung cocok, jika kartu tersebut memiliki teks ekstra seperti “Holomen ini juga dianggap sebagai 〈フワワ・アビスガード〉 dan 〈モココ・アビスガード〉”, maka kondisi tersebut tetap terpenuhi.","question":"Kemampuan kartu hBP03-109〈Ruffians〉 mengatakan “Kamu bisa mengirimkan Blue Ale dari archive kamu ke 〈フワワ・アビスガード〉 milikmu.” Apakah bisa juga mengirimkannya ke hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-109","hBP03-050","hBP03-043"],"raw_html":"[hBP03-109 ： Ruffians]\n[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q359（2025.03.11）"},{"answer":"Ya, bisa. hBP03-050〈FUWAMOCO〉 berwarna merah maupun biru, jadi memenuhi syarat.","question":"Jika Oshimen saya adalah hBP03-004〈FUWAMOCO〉, apakah saya bisa menambahkan hBP03-050〈FUWAMOCO〉 ke tangan dengan hBP03-084〈ゴージャスパソコン〉?","related_cards":{"card_number":["hBP03-050","hBP03-084","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-084 ： ゴージャスパソコン]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q340（2025.03.11）"},{"answer":"Ya, bisa. Walaupun nama kartu tidak langsung cocok, kartu dengan teks ekstra “Holomen ini juga dianggap sebagai 〈フワワ・アビスガード〉 dan 〈モココ・アビスガード〉” dianggap memenuhi syarat.","question":"Apakah saya bisa memindahkan ale ke hBP03-050〈FUWAMOCO〉 menggunakan arts “一緒に食べる?” dari hBP03-043〈フワワ・アビスガード〉?","related_cards":{"card_number":["hBP03-050","hBP03-043"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q322（2025.03.11）"},{"answer":"Ya, tetap mendapat. Bahkan jika nama kartu yang sesuai tidak ada, jika ada kartu yang di-extra menyatakan sesuatu seperti “holomen ini juga dianggap sebagai 〈フワワ・アビスガード〉〈モココ・アビスガード〉” sehingga memperlakukan sebagai nama kartu tertentu, maka kondisi itu terpenuhi.","question":"Apakah arts “もこもこしてる方” dari hBP03-039〈モココ・アビスガード〉 tetap mendapat “+30” bahkan jika center holomenku adalah hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q321（2025.03.11）"},{"answer":"可以，能造成傷害。即便卡片名稱中沒有該卡，如果在額外卡區（エクストラ）存在將某張卡指定為「此ホロメン也視為〈フワワ・アビスガード〉〈モココ・アビスガード〉」等以特定卡名扱う的卡，該條件仍然成立。","question":"hBP03-042〈フワワ・アビスガード〉的Bloom效果「Aliran bunga dan air Fuwa」，即使自己場上的其他ホロメン只有hBP03-050〈FUWAMOCO〉，也能造成特殊傷害「20」嗎？","related_cards":{"card_number":["hBP03-042","hBP03-050"],"raw_html":"[hBP03-042 ： フワワ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q320（2025.03.11）"},{"answer":"Ya, ia akan pindah tanpa menjadi istirahat. Bahkan jika nama kartu yang sesuai tidak ada, jika ada kartu yang di-extra menyatakan sesuatu seperti “holomen ini juga dianggap sebagai 〈フワワ・アビスガード〉〈モココ・アビスガード〉” sehingga memperlakukan sebagai nama kartu tertentu, maka kondisi itu terpenuhi.","question":"Apakah gift “魔界乃番犬の暴れん坊” dari hBP03-039〈モココ・アビスガード〉 tetap membuatnya pindah ke posisi back tanpa istirahat jika center holomenku adalah hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q319（2025.03.11）"},{"answer":"Ya, bisa. Walaupun nama kartu tidak cocok langsung, efek ekstra yang menyatakan Holomen ini dianggap sebagai 〈フワワ・アビスガード〉 dan 〈モココ・アビスガード〉 membuat syarat tersebut terpenuhi.","question":"Apakah kemampuan dari Bloom Effect “遊びの時間だー！” milik hBP03-038〈モココ・アビスガード〉 dapat menambahkan hBP03-050〈FUWAMOCO〉 ke tangan saya dari dek?","related_cards":{"card_number":["hBP03-050","hBP03-038"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-038 ： モココ・アビスガード]"},"title":"Q318（2025.03.11）"},{"answer":"Ya, bisa. Walaupun nama kartu tidak cocok langsung, efek ekstra yang menyatakan Holomen ini dianggap sebagai 〈フワワ・アビスガード〉 dan 〈モココ・アビスガード〉 membuat syarat tersebut terpenuhi.","question":"Apakah kemampuan oshiskill “モコちゃん！” dari hBP03-004〈FUWAMOCO〉 bisa mengirim ale ke hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q302（2025.03.11）"}],"ja":[{"answer":"カード名として、〈フワワ・アビスガード〉、〈モココ・アビスガード〉、〈FUWAMOCO〉を持つことを指します。","question":"hBP03-050〈FUWAMOCO〉のエクストラ能力「このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う」とは、どういう意味ですか？","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"はい、扱います。","question":"hBP03-050〈FUWAMOCO〉のエクストラ「このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う」とは、ステージ以外にある場合でも〈フワワ・アビスガード〉〈モココ・アビスガード〉として扱いますか？","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"はい、加えられます。","question":"hBP04-089〈ツートンカラーパソコン〉を使い、自分のステージに色が1色で異なる色のホロメンとして、〈ときのそら〉と〈フワワ・アビスガード〉を選びました。この場合、選んだホロメンと同色の1stホロメンとして、hSD01-013〈SorAZ〉とhBP03-050〈FUWAMOCO〉を手札に加えられますか？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"はい、されます。","question":"hBP04-049〈ムーナ・ホシノヴァ〉のアーツ「Shining Moon」の能力は、自分の他のホロメンがhBP03-050〈FUWAMOCO〉のみでも「+50」されますか？","related_cards":{"card_number":["hBP04-049","hBP03-050"],"raw_html":"[hBP04-049 ： ムーナ・ホシノヴァ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q390（2025.06.11）"},{"answer":"はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hBP03-109〈Ruffians〉の「自分のアーカイブの青エールを、自分の〈フワワ・アビスガード〉に送れる。」とは、hBP03-050〈FUWAMOCO〉にも送ることはできますか?","related_cards":{"card_number":["hBP03-109","hBP03-050","hBP03-043"],"raw_html":"[hBP03-109 ： Ruffians]\n[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q359（2025.03.11）"},{"answer":"はい、できます。hBP03-050〈FUWAMOCO〉は赤でも青でもあるため、条件を満たします。","question":"自分の推しホロメンがhBP03-004〈FUWAMOCO〉の時、hBP03-084〈ゴージャスパソコン〉でhBP03-050〈FUWAMOCO〉を手札に加えることはできますか？","related_cards":{"card_number":["hBP03-050","hBP03-084","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-084 ： ゴージャスパソコン]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q340（2025.03.11）"},{"answer":"はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hBP03-043〈フワワ・アビスガード〉のアーツ「一緒に食べる?」で、自分のhBP03-050〈FUWAMOCO〉にエールを付け替えることはできますか?","related_cards":{"card_number":["hBP03-050","hBP03-043"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q322（2025.03.11）"},{"answer":"はい、されます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hBP03-039〈モココ・アビスガード〉のアーツ「もこもこしてる方」は、自分のセンターホロメンがhBP03-050〈FUWAMOCO〉の場合でも「+30」されますか?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"titl