INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (726, 'hBP03-044', 'hBP03-044 えいひ JP 0期生 歌 星街すいせい #JP #0期生 #歌 バーチャルゴースト 自分の推しホロメンが〈星街すいせい〉の時、このホロメンの青エール1枚を、自分のバックホロメンの〈星街すいせい〉に付け替えられる。 プラネットステージ 自分のデッキの上から4枚を見る。その中から、〈星街すいせい〉1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。 Hoshimachi Suisei #JP #0th Gen #Singing Virtual Ghost If your oshi holomem is 〈Hoshimachi Suisei〉, you may move 1 Blue Cheer attached to this holomem to your Back holomem 〈Hoshimachi Suisei〉. Planet Stage Look at the top 4 cards of your deck. From among them, reveal 1 〈Hoshimachi Suisei〉 and add it to your hand. Then return the remaining cards to the bottom of your deck in any order. 星街彗星 #JP #0期生 #歌唱 虛擬幽靈 當自己的推しHolo成員為〈星街彗星〉時，可將這位Holo成員的1張藍色應援改附於自己的後台Holo成員〈星街彗星〉。 Planet Stage 查看自己牌庫最上方4張。從中公開1張〈星街彗星〉，加入手牌。然後將剩餘的牌以任意順序放回牌庫底。 Hoshimachi Suisei #JP #Gen 0 #Menyanyi Hantu Virtual Saat oshi holomen-mu adalah 〈Hoshimachi Suisei〉, kamu boleh memindahkan 1 Yell Biru dari holomen ini ke 〈Hoshimachi Suisei〉 milik salah satu Back holomen-mu. Panggung Planet Lihat 4 kartu teratas dari Deck milikmu. Dari antaranya, buka 1 kartu 〈Hoshimachi Suisei〉dan tambahkan ke tanganmu. Lalu kembalikan kartu sisanya ke bagian bawah Deck dalam urutan sesukamu. 호시마치 스이세이 #JP #0기생 #노래 버추얼 고스트 자신의 오시 홀로멘이 〈호시마치 스이세이〉일 때, 이 홀로멘의 블루 옐 1장을 자신의 백 홀로멘의 〈호시마치 스이세이〉로 갈아붙일 수 있다. 플래닛 스테이지 자신의 덱 위에서부터 4장을 본다. 그 중에서 〈호시마치 스이세이〉 1장을 공개하고, 손패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다. โฮชิมาชิ สุยเซย #JP #รุ่น 0 #เพลง โกสต์เสมือนจริง เมื่อโอชิโฮโลเมนของคุณคือ 〈โฮชิมาชิ สุยเซย〉 คุณสามารถย้าย เยลสีน้ำเงิน 1 ใบของโฮโลเมนนี้ไปติดกับ 〈โฮชิมาชิ สุยเซย〉 ของแบ็กโฮโลเมนของคุณได้ Planet Stage ดูการ์ด 4 ใบบนสุดของเด็คของคุณ จากนั้นเปิด〈โฮชิมาชิ สุยเซย〉1 ใบจากในนั้นแล้วนำขึ้นมือ แล้วนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับใดก็ได้ Hoshimachi Suisei #JP #0th Gen #Singing Fantasma virtual Si tu oshi holomen es 〈Hoshimachi Suisei〉, puedes mover 1 Blue Cheer de este holomen a tu 〈Hoshimachi Suisei〉 de Reserva. Escenario planetario Mira las 4 cartas superiores de tu mazo. De entre ellas, revela 1 〈Hoshimachi Suisei〉 y añádelo a tu mano. Luego devuelve las cartas restantes al fondo del mazo en el orden que prefieras.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('735', 'hBP03-055', 'character', 'SR', 'first', 'hBP03/hBP03-055_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-055_SR.png', 130, NULL, 1, '["null"]', '雨傘ゆん', '常闇トワ', '{"arts":[{"cost_types":["purple"],"damage":40},{"cost_types":["purple","null"],"damage":50}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["purple"],"translations":{"en":{"arts":[{"name":"It’s Fine If I Have a Home Date with Towa"},{"effect":"If you have a Back holomem with #Singing, deal 20 special damage to your opponent''s Collab holomem.","name":"Ten Q"}],"name":"Tokoyami Towa","tags":["#JP","#4th Gen","#Singing","#Shooter"]},"es":{"arts":[{"name":"Está bien si tengo una cita en casa con Towa"},{"effect":"Si tienes un holomen de Reserva que tenga #Singing, inflige 20 de daño especial al holomen de Colaboración del oponente.","name":"TenQ"}],"name":"Tokoyami Towa","tags":["#JP","#4th Gen","#Singing","#Shooter"]},"id":{"arts":[{"name":"Nggak apa-apa kan kalau kencan di rumah sama Towa"},{"effect":"Saat kamu memiliki Back holomen yang memiliki #Menyanyi, berikan 20 damage spesial kepada Collab holomen lawan.","name":"Ten-Q"}],"name":"Tokoyami Towa","tags":["#JP","#Gen 4","#Menyanyi","#Penembak"]},"ja":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"自分の#歌を持つバックホロメンがいる時、相手のコラボホロメンに特殊ダメージ20を与える。","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"ko":{"arts":[{"name":"토와와 집 데이트해도 돼"},{"effect":"자신의 #노래를 가진 백 홀로멘이 있을 때, 상대의 콜라보 홀로멘에게 특수 대미지 20을 준다.","name":"땡Q"}],"name":"토코야미 토와","tags":["#JP","#4기생","#노래","#슈터"]},"tc":{"arts":[{"name":"和永遠在家約會也沒關係"},{"effect":"當自己有持有#歌唱的後台Holo成員時，給予對手的合作Holo成員特殊傷害20。","name":"天Q"}],"name":"常闇永遠","tags":["#JP","#4期生","#歌唱","#射手"]},"th":{"arts":[{"name":"จะเดตที่บ้านกับ โทวะ ก็ได้นะ"},{"effect":"เมื่อคุณมีแบ็กโฮโลเมนที่มี #เพลง ให้สร้างความเสียหายพิเศษ 20 แก่คอลแลบโฮโลเมนของฝ่ายตรงข้าม","name":"แต๊งคิว"}],"name":"โทโคยามิ โทวะ","tags":["#JP","#รุ่น 4","#เพลง","#ชูตเตอร์"]}}}', '{}', '02c84b2e0c839944897c1f985b1d6ed60b5e2a59a9fa232bb7e9fc21acd4e671', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
