INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (735, 'hBP03-055', 'hBP03-055 雨傘ゆん JP 4期生 歌 シューター 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ 自分の#歌を持つバックホロメンがいる時、相手のコラボホロメンに特殊ダメージ20を与える。 Tokoyami Towa #JP #4th Gen #Singing #Shooter It’s Fine If I Have a Home Date with Towa Ten Q If you have a Back holomem with #Singing, deal 20 special damage to your opponent''s Collab holomem. 常闇永遠 #JP #4期生 #歌唱 #射手 和永遠在家約會也沒關係 天Q 當自己有持有#歌唱的後台Holo成員時，給予對手的合作Holo成員特殊傷害20。 Tokoyami Towa #JP #Gen 4 #Menyanyi #Penembak Nggak apa-apa kan kalau kencan di rumah sama Towa Ten-Q Saat kamu memiliki Back holomen yang memiliki #Menyanyi, berikan 20 damage spesial kepada Collab holomen lawan. 토코야미 토와 #JP #4기생 #노래 #슈터 토와와 집 데이트해도 돼 땡Q 자신의 #노래를 가진 백 홀로멘이 있을 때, 상대의 콜라보 홀로멘에게 특수 대미지 20을 준다. โทโคยามิ โทวะ #JP #รุ่น 4 #เพลง #ชูตเตอร์ จะเดตที่บ้านกับ โทวะ ก็ได้นะ แต๊งคิว เมื่อคุณมีแบ็กโฮโลเมนที่มี #เพลง ให้สร้างความเสียหายพิเศษ 20 แก่คอลแลบโฮโลเมนของฝ่ายตรงข้าม Tokoyami Towa #JP #4th Gen #Singing #Shooter Está bien si tengo una cita en casa con Towa TenQ Si tienes un holomen de Reserva que tenga #Singing, inflige 20 de daño especial al holomen de Colaboración del oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('1218', 'hBP05-040', 'character', 'U', 'first', 'hBP05/hBP05-040_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP05/hBP05-040_U.png', 150, NULL, 1, '["null"]', 'UIIV◇', 'miComet', '{"arts":[{"cost_types":["null","null","null"],"damage":90}],"card_sets":["ブースターパック「エンチャントレガリア」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red","blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"You may move 1 Cheer from this holomem to your back holomem.","name":"Business Partner"}],"extra":"This holomem is also treated as 〈Sakura Miko〉 and 〈Hoshimachi Suisei〉.","keyword":{"effect":"If your Life is 3 or less, your Center holomem that Bloomed this turn with [〈Sakura Miko〉 or 〈Hoshimachi Suisei〉] can Bloom one more time using a holomem from your hand.","name":"Business Friends"},"name":"miComet","tags":["#JP","#0th Gen","#Baby","#Singing"]},"es":{"arts":[{"effect":"Puedes cambiar de lugar 1 Cheer de este holomen para unirlo a uno de tus holomen de la Retaguardia.","name":"Socio de negocios"}],"extra":"Este holomen también se considera como 〈Sakura Miko〉 y 〈Hoshimachi Suisei〉","keyword":{"effect":"Si tu Vida es 3 o menos, tu holomen central [〈Sakura Miko〉 o 〈Hoshimachi Suisei〉] que haya hecho Bloom este turno puede hacer Bloom 1 vez más usando un holomen de tu mano.","name":"Amigos de negocios"},"name":"miComet","tags":["#JP","#0th Gen","#Baby","#Singing"]},"id":{"arts":[{"effect":"Kamu boleh memindahkan 1 Cheer pada holomen ini ke Back holomen milikmu.","name":"Partner Bisnis"}],"extra":"Holomen ini juga diperlakukan sebagai 〈Sakura Miko〉〈Hoshimachi Suisei〉","keyword":{"effect":"Jika Life milikmu 3 atau kurang, [〈Sakura Miko〉 atau 〈Hoshimachi Suisei〉] dari Center holomen milikmu yang Bloom pada giliran ini dapat Bloom 1 kali lagi menggunakan holomen dari tanganmu.","name":"Teman bisnis"},"name":"miComet","tags":["#JP","#Gen 0","#Bayi","#Menyanyi"]},"ja":{"arts":[{"effect":"このホロメンのエール1枚を自分のバックホロメンに付け替えられる。","name":"ビジネスパートナー"}],"extra":"このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う","keyword":{"effect":"自分のライフが3以下なら、自分のこのターンにBloomしたセンターホロメンの[〈さくらみこ〉か〈星街すいせい〉]を、自分の手札のホロメンを使ってもう1回Bloomできる。","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"ko":{"arts":[{"effect":"이 홀로멘의 에일 1장을 자신의 백 홀로멘에게 갈아붙일 수 있다.","name":"비즈니스 파트너"}],"extra":"이 홀로멤은 〈사쿠라 미코〉 〈호시마치 스이세이〉로도 취급한다","keyword":{"effect":"자신의 라이프가 3 이하라면, 자신이 이번 턴에 Bloom한 센터 홀로멘의 [〈사쿠라 미코〉 또는 〈호시마치 스이세이〉]는, 자신의 패의 홀로멘을 사용해 한 번 더 Bloom할 수 있다.","name":"비즈니스 프렌드"},"name":"miComet","tags":["#JP","#0기생","#베이비","#노래"]},"tc":{"arts":[{"effect":"可將此Holomen的1張應援改附給自己的後場Holomen。","name":"商業夥伴"}],"extra":"此Holo成員也視為〈櫻巫女〉〈星街彗星〉","keyword":{"effect":"若自己的生命值為3以下，則自己在這個回合Bloom的中位holomen的[〈櫻巫女〉或〈星街彗星〉]，可以使用自己手牌中的holomen再Bloom1次。","name":"商業朋友"},"name":"miComet","tags":["#JP","#0期生","#嬰兒","#歌唱"]},"th":{"arts":[{"effect":"คุณสามารถย้ายเอิล 1 ใบของโฮโลเมมนี้ไปติดกับโฮโลเมมตำแหน่งแบ็กของคุณได้","name":"พาร์ตเนอร์ทางธุรกิจ"}],"extra":"โฮโลเมมเบอร์นี้ให้นับเป็น〈ซากุระ มิโกะ〉〈โฮชิมาชิ สุยเซย〉ได้ด้วย","keyword":{"effect":"ถ้าไลฟ์ของคุณเหลือ 3 หรือน้อยกว่า [〈ซากุระ มิโกะ〉 หรือ 〈โฮชิมาชิ สุยเซย〉] ของเซ็นเตอร์โฮโลเมนที่ Bloom ในเทิร์นนี้ของคุณ สามารถ Bloom ได้อีก 1 ครั้งโดยใช้โฮโลเมนในมือของคุณ","name":"เพื่อนเชิงธุรกิจ"},"name":"miComet","tags":["#JP","#รุ่น 0","#เบบี้","#เพลง"]}}}', '{"en":[{"answer":"It means the card is considered to have the names 〈さくらみこ〉, 〈星街すいせい〉, and 〈miComet〉.","question":"What does the extra ability of hBP05-040〈miComet〉, “This Holomen is also treated as 〈さくらみこ〉 and 〈星街すいせい〉.” mean?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618 (2026.03.02)"},{"answer":"Yes, it does.","question":"For hBP05-040〈miComet〉’s extra ability “This Holomen is also treated as 〈さくらみこ〉 and 〈星街すいせい〉.” does it apply even when it is not on stage?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545 (2025.12.18)"}],"es":[{"answer":"Significa que la carta posee los nombres 〈さくらみこ〉, 〈星街すいせい〉 y 〈miComet〉 como nombres de carta.","question":"¿Qué significa la habilidad extra “Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉” de hBP05-040〈miComet〉?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"Sí, se trata como tal.","question":"En el caso de la habilidad extra “Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉” de hBP05-040〈miComet〉, ¿se trata también como 〈さくらみこ〉 y 〈星街すいせい〉 incluso si no está en el escenario?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"id":[{"answer":"Itu berarti kartu ini memiliki nama〈さくらみこ〉,〈星街すいせい〉, dan〈miComet〉.","question":"Apa arti dari kemampuan ekstra hBP05-040〈miComet〉『Holomen ini juga dianggap sebagai〈さくらみこ〉〈星街すいせい〉』?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"Ya, tetap dianggap demikian.","question":"Apakah kemampuan ekstra hBP05-040〈miComet〉『Holomen ini juga dianggap sebagai〈さくらみこ〉〈星街すいせい〉』berlaku juga ketika tidak berada di Stage?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"ja":[{"answer":"カード名として、〈さくらみこ〉、〈星街すいせい〉、〈miComet〉を持つことを指します。","question":"hBP05-040〈miComet〉のエクストラ能力「このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う」とは、どういう意味ですか？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"はい、扱います。","question":"hBP05-040〈miComet〉のエクストラ「このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う」とは、ステージ以外にある場合でも〈さくらみこ〉〈星街すいせい〉として扱いますか？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"ko":[{"answer":"카드 이름으로서 〈さくらみこ〉, 〈星街すいせい〉, 〈miComet〉을 모두 가진다는 의미입니다.","question":"hBP05-040〈miComet〉의 엑스트라 능력 「이 홀로멘은〈さくらみこ〉〈星街すいせい〉로도 취급한다」는 어떤 의미인가요?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"네, 그렇게 취급합니다.","question":"hBP05-040〈miComet〉의 엑스트라 「이 홀로멘은〈さくらみこ〉〈星街すいせい〉로도 취급한다」는, 스테이지 외에 있을 때도〈さくらみこ〉〈星街すいせい〉로 취급하나요?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"tc":[{"answer":"表示作為卡名同時擁有〈さくらみこ〉、〈星街すいせい〉與〈miComet〉。","question":"hBP05-040〈miComet〉的額外能力「此Holomen也視為〈さくらみこ〉與〈星街すいせい〉。」是什麼意思？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"是的，無論在哪裡都視為相同。","question":"hBP05-040〈miComet〉的額外效果「此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。」在不在舞台上時也會當作〈さくらみこ〉與〈星街すいせい〉嗎？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"th":[{"answer":"หมายถึงถือว่าเป็นการ์ดที่มีชื่อ〈さくらみこ〉, 〈星街すいせい〉 และ〈miComet〉","question":"ความหมายของความสามารถพิเศษ “โฮโลเมมเบอร์นี้จะถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย” บนการ์ด hBP05-040〈miComet〉 คืออะไร?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"ใช่ ถือว่าเป็นเช่นนั้น","question":"เอ็กซ์ตร้า “โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย” ของ hBP05-040〈miComet〉 จะยังถือว่าเป็น〈さくらみこ〉หรือ〈星街すいせい〉แม้อยู่ในพื้นที่อื่นนอกจากสเตจหรือไม่?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}]}', 'a6a0419f7bf1959b7793290cd35f33e0517c0e9c01920737a305a2eaf95d2bbc', '6672e66fbb3fcb6777a5de7b9305b470ddeb1b9412082be26a04e46e2417b10b', '1970-01-01T00:00:00Z');
