INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2138', 'hBP03-044', 'character', 'SR', 'first', 'hCO01/hBP03-044_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hCO01/hBP03-044_SR.png', 150, NULL, 1, '["null"]', 'Mika Pikazo', '星街すいせい', '{"arts":[{"cost_types":["blue","null"],"damage":40}],"card_sets":["オフィシャルホロカコレクション-2025ライブセット-","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If your oshi holomem is 〈Hoshimachi Suisei〉, you may move 1 Blue Cheer attached to this holomem to your Back holomem 〈Hoshimachi Suisei〉.","name":"Virtual Ghost"}],"keyword":{"effect":"Look at the top 4 cards of your deck. From among them, reveal 1 〈Hoshimachi Suisei〉 and add it to your hand. Then return the remaining cards to the bottom of your deck in any order.","name":"Planet Stage"},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"effect":"Si tu oshi holomen es 〈Hoshimachi Suisei〉, puedes mover 1 Blue Cheer de este holomen a tu 〈Hoshimachi Suisei〉 de Reserva.","name":"Fantasma virtual"}],"keyword":{"effect":"Mira las 4 cartas superiores de tu mazo. De entre ellas, revela 1 〈Hoshimachi Suisei〉 y añádelo a tu mano. Luego devuelve las cartas restantes al fondo del mazo en el orden que prefieras.","name":"Escenario planetario"},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"effect":"Saat oshi holomen-mu adalah 〈Hoshimachi Suisei〉, kamu boleh memindahkan 1 Yell Biru dari holomen ini ke 〈Hoshimachi Suisei〉 milik salah satu Back holomen-mu.","name":"Hantu Virtual"}],"keyword":{"effect":"Lihat 4 kartu teratas dari Deck milikmu. Dari antaranya, buka 1 kartu 〈Hoshimachi Suisei〉dan tambahkan ke tanganmu. Lalu kembalikan kartu sisanya ke bagian bawah Deck dalam urutan sesukamu.","name":"Panggung Planet"},"name":"Hoshimachi Suisei","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"effect":"自分の推しホロメンが〈星街すいせい〉の時、このホロメンの青エール1枚を、自分のバックホロメンの〈星街すいせい〉に付け替えられる。","name":"バーチャルゴースト"}],"keyword":{"effect":"自分のデッキの上から4枚を見る。その中から、〈星街すいせい〉1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"자신의 오시 홀로멘이 〈호시마치 스이세이〉일 때, 이 홀로멘의 블루 옐 1장을 자신의 백 홀로멘의 〈호시마치 스이세이〉로 갈아붙일 수 있다.","name":"버추얼 고스트"}],"keyword":{"effect":"자신의 덱 위에서부터 4장을 본다. 그 중에서 〈호시마치 스이세이〉 1장을 공개하고, 손패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.","name":"플래닛 스테이지"},"name":"호시마치 스이세이","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"effect":"當自己的推しHolo成員為〈星街彗星〉時，可將這位Holo成員的1張藍色應援改附於自己的後台Holo成員〈星街彗星〉。","name":"虛擬幽靈"}],"keyword":{"effect":"查看自己牌庫最上方4張。從中公開1張〈星街彗星〉，加入手牌。然後將剩餘的牌以任意順序放回牌庫底。","name":"Planet Stage"},"name":"星街彗星","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"effect":"เมื่อโอชิโฮโลเมนของคุณคือ 〈โฮชิมาชิ สุยเซย〉 คุณสามารถย้าย เยลสีน้ำเงิน 1 ใบของโฮโลเมนนี้ไปติดกับ 〈โฮชิมาชิ สุยเซย〉 ของแบ็กโฮโลเมนของคุณได้","name":"โกสต์เสมือนจริง"}],"keyword":{"effect":"ดูการ์ด 4 ใบบนสุดของเด็คของคุณ จากนั้นเปิด〈โฮชิมาชิ สุยเซย〉1 ใบจากในนั้นแล้วนำขึ้นมือ แล้วนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับใดก็ได้","name":"Planet Stage"},"name":"โฮชิมาชิ สุยเซย","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '9da07d9bad0c9f4168fff52d5950d36626a2ee2b3d992e9fae864557224f8d13', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
