INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (2164, 'hBP03-011', 'hBP03-011 葉桜ちこり JP 4期生 ベイビー 姫森ルーナ #JP #4期生 #ベイビー おつルーナ ぐっどないと～ Himemori Luna #JP #4th Gen #Baby Otsuluna Gooood night~ 姬森璐娜 #JP #4期生 #嬰兒 辛苦啦露娜～ 晚安～ Himemori Luna #JP #Gen 4 #Bayi Otsuruna Good night～ 히메모리 루나 #JP #4기생 #베이비 오츠루나 굿나잇~ ฮิเมโมริ ลูนะ #JP #รุ่น 4 #เบบี้ โอสึลูน่า กู๊ดไนท์~ Himemori Luna #JP #4th Gen #Baby OtsuLuna Buenas nocheees~', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2263', 'hBP08-060', 'character', 'R', 'first', 'hBP08/hBP08-060_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP08/hBP08-060_R.png', 170, NULL, 1, '["null"]', '兎未枝', 'FUWAMOCO', '{"arts":[{"cost_types":["null","null"],"damage":50}],"card_sets":["ブースターパック バウンサーバウンド","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue","red"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"effect":"If your oshi holomem is blue 〈FUWAMOCO〉, put the top card of your Deck into your holoPower.","name":"Together Forever♡"}],"extra":"This holomem is also treated as 〈Fuwawa Abyssgard〉 and 〈Mococo Abyssgard〉.","keyword":{"effect":"[Collab Position Only] Change your oshi skill \"Mococo-chan!\" [holoPower:-3] to [holoPower:-2].","name":"\"BAU\" DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#Animal Ears"]},"es":{"arts":[{"effect":"Si tu Oshi holomem es el 〈FUWAMOCO〉 azul, pon la carta superior de tu Mazo en tu Holo Power.","name":"Juntas para siempre♡"}],"extra":"Este holomen también se considera como 〈Fuwawa Abyssgard〉 y 〈Mococo Abyssgard〉","keyword":{"effect":"[Solo Posición de Colaboración] Cambia el [holoPower:-3] de tu habilidad Oshi «モコちゃん！」 a [holoPower:-2].","name":"“BAU” DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#Animal Ears"]},"id":{"arts":[{"effect":"Jika Oshi holomen milikmu adalah 〈FUWAMOCO〉 biru, jadikan 1 kartu teratas Deck milikmu sebagai Holo Power.","name":"Selamanya bersama♡"}],"extra":"Holomen ini juga diperlakukan sebagai 〈Fuwawa Abyssgard〉〈Mococo Abyssgard〉","keyword":{"effect":"[Hanya Posisi Collab] Ubah [holo Power:-3] dari oshi skill milikmu \"モコちゃん！\" menjadi [holo Power:-2].","name":"“BAU” DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#Telinga Hewan"]},"ja":{"arts":[{"effect":"自分の推しホロメンが青の〈FUWAMOCO〉なら、自分のデッキの上から1枚をホロパワーにする。","name":"いっしょういっしょ♡"}],"extra":"このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う","keyword":{"effect":"[コラボポジション限定]自分の推しスキル「モコちゃん！」の[ホロパワー:-3]を[ホロパワー:-2]に変更する。","name":"“BAU” DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"ko":{"arts":[{"effect":"자신의 오시 홀로멘이 파란색 〈FUWAMOCO〉라면, 자신의 덱 맨 위에서 1장을 홀로파워로 한다.","name":"평생 함께♡"}],"extra":"이 홀로멤은 〈후와와 어비스가드〉 〈모코코 어비스가드〉로도 취급한다","keyword":{"effect":"[콜라보 포지션 한정] 자신의 오시 스킬 「모코짱!」의 [홀로파워:-3]을 [홀로파워:-2]로 변경한다.","name":"“BAU” DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#수인귀"]},"tc":{"arts":[{"effect":"若自己的推Holo成員是藍色的〈FUWAMOCO〉，將自己牌庫頂的1張卡作為Holo能量。","name":"一生都要在一起♡"}],"extra":"此Holo成員也視為〈Fuwawa Abyssguard〉〈Mococo Abyssguard〉","keyword":{"effect":"[Collab位置限定]將自己的推技能「Moco醬！」的[Holo Power:-3]變更為[Holo Power:-2]。","name":"“BAU” DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#獸耳"]},"th":{"arts":[{"effect":"ถ้าโอชิโฮโลเมนของคุณเป็น〈FUWAMOCO〉สีน้ำเงิน ให้นำการ์ดใบบนสุดจากเด็คของคุณไปเป็นโฮโลพาวเวอร์","name":"อยู่ด้วยกันตลอดไป♡"}],"extra":"โฮโลเมมเบอร์นี้ให้นับเป็น〈ฟุวาวา อะบิสการ์ด〉〈โมโคโคะ อะบิสการ์ด〉ได้ด้วย","keyword":{"effect":"[เฉพาะตำแหน่งคอลแลบ] เปลี่ยน [โฮโลพาวเวอร์:-3] ของโอชิสกิล「โมโกะจัง!」ของคุณเป็น [โฮโลพาวเวอร์:-2]","name":"“BAU” DOL♡"},"name":"FUWAMOCO","tags":["#EN","#Advent","#หูสัตว์"]}}}', '{}', '29c8592da420c4d26e0c269a9c37c767e692027914503fbf87c2e491a0a7361e', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
