INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (2444, 'hBP01-028', 'hBP01-028 がり EN Promise 歌 IRyS #EN #Promise #歌 このホロメンはデッキに何枚でも入れられる ハイRyS！ IRyS #EN #Promise #Singing You may include any number of copies of this holomem in your deck. HiRyS! IRyS #EN #Promise #歌唱 此Holo成員可放入牌組任意張數 HiRyS！ IRyS #EN #Promise #Menyanyi Holomen ini dapat dimasukkan ke dalam deck sebanyak apa pun HaiRyS! IRyS #EN #Promise #노래 이 홀로멤은 덱에 몇 장이든 넣을 수 있다 하이RyS! IRyS #EN #Promise #เพลง ใส่โฮโลเมมเบอร์นี้ในเด็คได้กี่ใบก็ได้ HiRyS! IRyS #EN #Promise #Singing Se puede incluir cualquier cantidad de copias de este holomen en el mazo HiRyS!', '');
